                                    <input
                                        type="text"
                                        value={editForm.woIncentiveRate ? Number(editForm.woIncentiveRate).toLocaleString('id-ID') : ''}
                                        onChange={(e) => setEditForm({ ...editForm, woIncentiveRate: e.target.value.replace(/\D/g, '') })}
                                        className="w-full px-2.5 py-1.5 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                        placeholder="0"
                                    />
                                </div>

                                {/* Potongan Telat */}
                                <div className="bg-red-50/60 dark:bg-red-900/10 p-2.5 rounded-lg border border-red-100 dark:border-red-700/20">
                                    <label className="block text-xs text-red-600 dark:text-red-400 mb-1 font-medium">-Telat</label>
                                    <input
                                        type="text"
                                        value={editForm.lateDeductionRate ? Number(editForm.lateDeductionRate).toLocaleString('id-ID') : ''}
                                        onChange={(e) => setEditForm({ ...editForm, lateDeductionRate: e.target.value.replace(/\D/g, '') })}
                                        className="w-full px-2.5 py-1.5 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                        placeholder="0"
                                    />
                                </div>

                                {/* Potongan Alpha */}
                                <div className="bg-red-50/60 dark:bg-red-900/10 p-2.5 rounded-lg border border-red-100 dark:border-red-700/20">
                                    <label className="block text-xs text-red-600 dark:text-red-400 mb-1 font-medium">-Alpha</label>
                                    <input
                                        type="text"
                                        value={editForm.absentDeductionRate ? Number(editForm.absentDeductionRate).toLocaleString('id-ID') : ''}
                                        onChange={(e) => setEditForm({ ...editForm, absentDeductionRate: e.target.value.replace(/\D/g, '') })}
                                        className="w-full px-2.5 py-1.5 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                        placeholder="0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Komponen Gaji Tambahan Section */}
                        <div className="border-t border-gray-100 dark:border-gray-700/50 pt-4">
                            <h4 className="font-medium mb-3 text-sm text-gray-600 dark:text-gray-400 flex items-center gap-2">
                                <span className="w-5 h-5 rounded-md bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-500 dark:text-indigo-400">
                                    <HiOutlineDocumentText className="w-3 h-3" />
                                </span>
                                Kelola Komponen Gaji Tambahan
                            </h4>

                            <div className="space-y-4">
                                {/* Existing Components List - Moved to Top */}
                                <div className="space-y-2">
                                    {userComponents.length > 0 ? (
                                        userComponents.map((uc) => (
                                            <div
                                                key={uc.id}
                                                className={`flex items-center justify-between px-3 py-2 rounded-xl text-sm transition-all duration-200 hover:shadow-md border ${
                                                    uc.component.type === 'EARNING'
                                                        ? 'bg-linear-to-r from-green-50 to-emerald-50/50 dark:from-green-900/20 dark:to-emerald-900/10 border-green-200/60 dark:border-green-700/40 hover:border-green-300'
                                                        : 'bg-linear-to-r from-red-50 to-rose-50/50 dark:from-red-900/20 dark:to-rose-900/10 border-red-200/60 dark:border-red-700/40 hover:border-red-300'
                                                }`}
                                            >
                                                <div className="flex items-center gap-2">
                                                    <span className={`w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold ${
                                                        uc.component.type === 'EARNING' 
                                                            ? 'bg-green-500 text-white' 
                                                            : 'bg-red-500 text-white'
                                                    }`}>
                                                        {uc.component.type === 'EARNING' ? '+' : '-'}
                                                    </span>
                                                    <span className="font-medium text-gray-700 dark:text-gray-200">{uc.component.name}</span>
                                                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-medium ${
                                                        uc.component.rateType === 'PERCENTAGE'
                                                            ? 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400' 
                                                            : 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
                                                    }`}>
                                                        {uc.component.rateType === 'PERCENTAGE' ? '%' : 'Fix'}
                                                    </span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <span className={`font-semibold ${
                                                        uc.component.type === 'EARNING' 
                                                            ? 'text-green-600 dark:text-green-400' 
                                                            : 'text-red-600 dark:text-red-400'
                                                    }`}>
                                                        {uc.component.rateType === 'PERCENTAGE'
                                                            ? `${uc.amount}%` 
                                                            : formatCurrency(uc.amount)
                                                        }
                                                    </span>
                                                    <button
                                                        onClick={() => handleRemoveComponent(uc.id)}
                                                        className="p-1.5 hover:bg-red-100 dark:hover:bg-red-900/30 rounded-lg text-red-400 hover:text-red-600 transition-colors"
                                                    >
                                                        <HiOutlineTrash className="w-3.5 h-3.5" />
                                                    </button>
                                                </div>
                                            </div>
                                        ))
                                    ) : (
                                        <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-3 text-sm text-center">
                                            <p className="text-yellow-700 dark:text-yellow-300">
                                                Belum ada komponen aktif.
                                            </p>
                                        </div>
                                    )}
                                </div>

                                {/* Add Component Form - Direct Input (Matches Add Modal Grid Exactly) */}
                                <div className="space-y-2">
                                    <div className="grid grid-cols-12 gap-2">
                                        <input
                                            type="text"
                                            value={newComponentName}
                                            onChange={(e) => setNewComponentName(e.target.value)}
                                            placeholder="Nama komponen"
                                            className="col-span-4 px-3 py-2 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                        />
                                        <select
                                            value={newComponentType}
                                            onChange={(e) => setNewComponentType(e.target.value as 'EARNING' | 'DEDUCTION')}
                                            className="col-span-2 px-2 py-2 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                        >
                                            <option value="EARNING">+ Pend</option>
                                            <option value="DEDUCTION">- Pot</option>
                                        </select>
                                        <select
                                            value={newComponentRateType}
                                            onChange={(e) => setNewComponentRateType(e.target.value as 'FIXED' | 'PERCENTAGE')}
                                            className="col-span-2 px-2 py-2 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                        >
                                            <option value="FIXED">Fix (Rp)</option>
                                            <option value="PERCENTAGE">% Gaji</option>
                                        </select>
                                        <div className="col-span-3">
                                            <input
                                                type="text"
                                                value={newComponentAmount ? (newComponentRateType === 'PERCENTAGE' ? newComponentAmount : Number(newComponentAmount).toLocaleString('id-ID')) : ''}
                                                onChange={(e) => {
                                                    const val = e.target.value
                                                    if (newComponentRateType === 'PERCENTAGE') {
                                                        setNewComponentAmount(val.replace(/[^\d.]/g, ''))
                                                    } else {
                                                        setNewComponentAmount(val.replace(/\D/g, ''))
                                                    }
                                                }}
                                                placeholder={newComponentRateType === 'PERCENTAGE' ? '5' : '500.000'}
                                                className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
                                            />
                                        </div>
                                        <button
                                            type="button"
                                            onClick={handleCreateAndAssignComponent}
                                            className="col-span-1 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-medium transition-colors flex items-center justify-center"
                                            title="Tambah Komponen"
                                        >
                                            <HiOutlinePlus className="w-5 h-5" />
                                        </button>
                                    </div>
                                    <p className="text-xs text-gray-500">
                                        Komponen yang ditambahkan akan langsung disimpan.
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* Footer Actions - Matching Add Modal */}
                        <div className="flex gap-3 pt-4 border-t border-gray-100 dark:border-gray-800">
                            <button
                                type="button"
                                onClick={handleUpdateUser}
                                className="flex-1 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium shadow-sm transition-colors flex items-center justify-center gap-2"
                            >
                                <HiOutlineCheckCircle className="w-5 h-5" />
                                Simpan Perubahan
                            </button>
                            <button
                                type="button"
                                onClick={() => setShowEditModal(false)}
                                className="px-4 py-2 border border-gray-300 rounded-lg font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors text-gray-700 dark:text-gray-200"
                            >
                                Batal
                            </button>
                        </div>
                    </div>
                )}
            </Modal>

        </div>
    )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import {
    HiOutlineChatBubbleLeftRight,
    HiOutlineMagnifyingGlass,
    HiOutlineArrowPath,
    HiChevronLeft,
    HiChevronRight,
    HiOutlineTicket,
    HiOutlineClock,
    HiOutlineCheckCircle,
    HiOutlineStar,
} from 'react-icons/hi2'
import { formatDistanceToNow, format } from 'date-fns'
import { id } from 'date-fns/locale'
import ResponsiveTable from '@/components/ui/ResponsiveTable'

interface Ticket {
    id: string
    ticketNumber: string
    subject: string
    description: string
    status: string
    priority: string
    category: string
    createdAt: string
    updatedAt: string
    pelanggan: {
        id: string
        idPelanggan: string
        nama: string
        noTelp: string | null
        email: string | null
    }
    assignedTo: {
        id: string
        name: string
    } | null
    lastReply?: {
        isFromAdmin: boolean
        createdAt: string
        message?: string
    } | null
    replyCount: number
}

interface Stats {
    total: number
    open: number
    inProgress: number
    waitingCustomer: number
    resolved: number
    closed: number
    avgRating: number
    ratedCount: number
}

export default function SupportContext() {
    const router = useRouter()
    const [tickets, setTickets] = useState<Ticket[]>([])
    const [loading, setLoading] = useState(true)
    const [page, setPage] = useState(1)
    const [totalPages, setTotalPages] = useState(1)
    const [total, setTotal] = useState(0)
    const [search, setSearch] = useState('')
    const [statusFilter, setStatusFilter] = useState('')
    const [categoryFilter, setCategoryFilter] = useState('')
    const [priorityFilter, setPriorityFilter] = useState('')
    const [stats, setStats] = useState<Stats>({
        total: 0,
        open: 0,
        inProgress: 0,
        waitingCustomer: 0,
        resolved: 0,
        closed: 0,
        avgRating: 0,
        ratedCount: 0,
    })

    const loadTickets = useCallback(async () => {
        setLoading(true)
        try {
            const params = new URLSearchParams()
            params.set('page', page.toString())
            params.set('limit', '20')
            if (search) params.set('search', search)
            if (statusFilter) params.set('status', statusFilter)
            if (categoryFilter) params.set('category', categoryFilter)
            if (priorityFilter) params.set('priority', priorityFilter)

            const res = await fetch(`/api/admin/support-tickets?${params.toString()}`)
            if (res.ok) {
                const data = await res.json()
                const responseData = data.data || data
                setTickets(responseData.tickets || [])
                setTotalPages(responseData.pagination?.totalPages || 1)
                setTotal(responseData.pagination?.total || 0)
                if (responseData.stats) {
                    setStats(responseData.stats)
                }
            }
        } catch (error) {
            console.error('Error loading tickets:', error)
        } finally {
            setLoading(false)
        }
    }, [page, search, statusFilter, categoryFilter, priorityFilter])

    useEffect(() => {
        loadTickets()
    }, [loadTickets])

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'OPEN':
                return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
            case 'IN_PROGRESS':
                return 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
            case 'WAITING_CUSTOMER':
                return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
            case 'RESOLVED':
                return 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
            case 'CLOSED':
                return 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-400'
            default:
                return 'bg-gray-100 text-gray-700'
        }
    }

    const getStatusLabel = (status: string) => {
        switch (status) {
            case 'OPEN': return 'Baru'
            case 'IN_PROGRESS': return 'Dalam Proses'
            case 'WAITING_CUSTOMER': return 'Menunggu Pelanggan'
            case 'RESOLVED': return 'Selesai Dikerjakan'
            case 'CLOSED': return 'Ditutup'
            default: return status
        }
    }

    const getPriorityColor = (priority: string) => {
        switch (priority) {
            case 'URGENT': return 'bg-red-500'
            case 'HIGH': return 'bg-orange-500'
            case 'MEDIUM': return 'bg-yellow-500'
            default: return 'bg-gray-400'
        }
    }

    const getCategoryLabel = (category: string) => {
        switch (category) {
            case 'TECHNICAL': return 'Teknis'
            case 'BILLING': return 'Tagihan'
            case 'ACCOUNT': return 'Akun'
            case 'OTHER': return 'Lainnya'
            default: return category
        }
    }

    // Extract rating from closed ticket's last message
    const extractRating = (ticket: Ticket): number | null => {
        if (ticket.status !== 'CLOSED' || !ticket.lastReply?.message) return null

        const message = ticket.lastReply.message
        if (message.includes('⭐⭐⭐⭐⭐')) return 5
        if (message.includes('⭐⭐⭐⭐')) return 4
        if (message.includes('⭐⭐⭐')) return 3
        if (message.includes('⭐⭐')) return 2
        if (message.includes('⭐')) return 1
        return null
    }

    const renderStars = (rating: number | null) => {
        if (rating === null) return <span className="text-gray-400 text-xs">-</span>
        return (
            <div className="flex items-center gap-0.5">
                {[1, 2, 3, 4, 5].map((star) => (
                    <span
                        key={star}
                        className={star <= rating ? 'text-yellow-400' : 'text-gray-300'}
                    >
                        ★
                    </span>
                ))}
            </div>
        )
    }

    return (
        <div className="p-6 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <HiOutlineChatBubbleLeftRight className="w-7 h-7 text-teal-600" />
                        Tiket Dukungan Pelanggan
                    </h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        Kelola tiket dukungan dari pelanggan
                    </p>
                </div>
                <button
                    onClick={loadTickets}
                    className="flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors"
                >
                    <HiOutlineArrowPath className="w-4 h-4" />
                    Refresh
                </button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                {/* Total Tickets */}
                <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 p-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-teal-100 dark:bg-teal-900/30 rounded-lg">
                            <HiOutlineTicket className="w-5 h-5 text-teal-600 dark:text-teal-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.total}</p>
                            <p className="text-xs text-gray-500">Total Tiket</p>
                        </div>
                    </div>
                </div>

                {/* Open/New Tickets */}
                <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 p-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-red-100 dark:bg-red-900/30 rounded-lg">
                            <HiOutlineClock className="w-5 h-5 text-red-600 dark:text-red-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.open + stats.inProgress}</p>
                            <p className="text-xs text-gray-500">Perlu Ditangani</p>
                        </div>
                    </div>
                </div>

                {/* Closed Tickets */}
                <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 p-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg">
                            <HiOutlineCheckCircle className="w-5 h-5 text-green-600 dark:text-green-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.closed}</p>
                            <p className="text-xs text-gray-500">Selesai</p>
                        </div>
                    </div>
                </div>

                {/* Average Rating */}
                <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 p-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-yellow-100 dark:bg-yellow-900/30 rounded-lg">
                            <HiOutlineStar className="w-5 h-5 text-yellow-600 dark:text-yellow-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-gray-900 dark:text-white">
                                {stats.avgRating > 0 ? stats.avgRating.toFixed(1) : '-'}
                            </p>
                            <p className="text-xs text-gray-500">
                                Rating {stats.ratedCount > 0 ? `(${stats.ratedCount})` : ''}
                            </p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 p-4 mb-6">
                <div className="flex flex-wrap gap-4">
                    {/* Search */}
                    <div className="flex-1 min-w-[200px]">
                        <div className="relative">
                            <HiOutlineMagnifyingGlass className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                            <input
                                type="text"
                                placeholder="Cari tiket atau pelanggan..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                            />
                        </div>
                    </div>

                    {/* Status Filter */}
                    <select
                        value={statusFilter}
                        onChange={(e) => setStatusFilter(e.target.value)}
                        className="px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                    >
                        <option value="">Semua Status</option>
                        <option value="OPEN">Baru</option>
                        <option value="IN_PROGRESS">Dalam Proses</option>
                        <option value="WAITING_CUSTOMER">Menunggu Pelanggan</option>
                        <option value="RESOLVED">Selesai</option>
                        <option value="CLOSED">Ditutup</option>
                    </select>

                    {/* Category Filter */}
                    <select
                        value={categoryFilter}
                        onChange={(e) => setCategoryFilter(e.target.value)}
                        className="px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                    >
                        <option value="">Semua Kategori</option>
                        <option value="TECHNICAL">Teknis</option>
                        <option value="BILLING">Tagihan</option>
                        <option value="ACCOUNT">Akun</option>
                        <option value="OTHER">Lainnya</option>
                    </select>

                    {/* Priority Filter */}
                    <select
                        value={priorityFilter}
                        onChange={(e) => setPriorityFilter(e.target.value)}
                        className="px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                    >
                        <option value="">Semua Prioritas</option>
                        <option value="URGENT">Urgent</option>
                        <option value="HIGH">Tinggi</option>
                        <option value="MEDIUM">Medium</option>
                        <option value="LOW">Rendah</option>
                    </select>
                </div>
            </div>

            {/* Tickets Table */}
            <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 overflow-hidden">
                <ResponsiveTable
                    data={tickets}
                    keyField="id"
                    loading={loading}
                    onRowClick={(ticket) => router.push(`/admin/support/${ticket.id}`)}
                    emptyMessage={
                        <div className="text-center py-12">
                            <HiOutlineChatBubbleLeftRight className="w-12 h-12 mx-auto mb-3 opacity-30" />
                            <p>Tidak ada tiket ditemukan</p>
                        </div>
                    }
                    columns={[
                        {
                            key: 'ticketNumber',
                            header: 'Tiket',
                            priority: 'primary',
                            render: (ticket: Ticket) => (
                                <div className="flex items-center gap-3">
                                    <div className={`w-1.5 h-10 rounded-full ${getPriorityColor(ticket.priority)}`} />
                                    <div>
                                        <div className="font-medium text-gray-900 dark:text-white">
                                            {ticket.subject}
                                        </div>
                                        <div className="text-xs text-gray-500 font-mono">
                                            #{ticket.ticketNumber}
                                        </div>
                                    </div>
                                </div>
                            )
                        },
                        {
                            key: 'pelanggan',
                            header: 'Pelanggan',
                            priority: 'primary',
                            render: (ticket: Ticket) => (
                                <div>
                                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                                        {ticket.pelanggan.nama}
                                    </div>
                                    <div className="text-xs text-gray-500">
                                        {ticket.pelanggan.idPelanggan}
                                    </div>
                                </div>
                            )
                        },
                        {
                            key: 'status',
                            header: 'Status',
                            priority: 'secondary',
                            render: (ticket: Ticket) => (
                                <span className={`inline-flex px-2.5 py-1 text-xs font-medium rounded-full ${getStatusColor(ticket.status)}`}>
                                    {getStatusLabel(ticket.status)}
                                </span>
                            )
                        },
                        {
                            key: 'category',
                            header: 'Kategori',
                            priority: 'secondary',
                            render: (ticket: Ticket) => (
                                <span className="text-sm text-gray-600 dark:text-gray-400">{getCategoryLabel(ticket.category)}</span>
                            )
                        },
                        {
                            key: 'createdAt',
                            header: 'Dibuat',
                            priority: 'tertiary',
                            render: (ticket: Ticket) => (
                                <div>
                                    <div className="text-sm text-gray-900 dark:text-white">
                                        {format(new Date(ticket.createdAt), 'dd MMM yyyy', { locale: id })}
                                    </div>
                                    <div className="text-xs text-gray-500">
                                        {formatDistanceToNow(new Date(ticket.createdAt), { addSuffix: true, locale: id })}
                                    </div>
                                </div>
                            )
                        },
                        {
                            key: 'replyCount',
                            header: 'Balasan',
                            priority: 'tertiary',
                            render: (ticket: Ticket) => (
                                <div className="flex items-center gap-2">
                                    <span className="text-sm font-medium text-gray-900 dark:text-white">
                                        {ticket.replyCount}
                                    </span>
                                    {ticket.lastReply && !ticket.lastReply.isFromAdmin && ticket.status !== 'RESOLVED' && ticket.status !== 'CLOSED' && (
                                        <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" title="Perlu balasan" />
                                    )}
                                </div>
                            )
                        },
                        {
                            key: 'rating',
                            header: 'Rating',
                            priority: 'tertiary',
                            render: (ticket: Ticket) => renderStars(extractRating(ticket))
                        }
                    ]}
                />

                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700">
                        <div className="text-sm text-gray-500">
                            Halaman {page} dari {totalPages}
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => setPage(Math.max(1, page - 1))}
                                disabled={page === 1}
                                className="p-2 rounded-lg border border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <HiChevronLeft className="w-4 h-4" />
                            </button>
                            <button
                                onClick={() => setPage(Math.min(totalPages, page + 1))}
                                disabled={page === totalPages}
                                className="p-2 rounded-lg border border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <HiChevronRight className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
}

/**
 * Admin Attendance Single Record Routes
 * Migrated to use standardized middleware and validation
 */

import { prisma } from '@/lib/prisma'
import { Prisma } from '@prisma/client'
import {
  withAuth, 
  withPermission, 
  withErrorHandler, 
  withRateLimit,
  RateLimits,
  ValidationError,
  NotFoundError,
  applyRBACRestrictions
} from '@/lib/middleware'
import { apiSuccess } from '@/lib/api-response'
import { attendanceUpdateSchema } from '@/lib/validations/attendance'
import { idSchema } from '@/lib/validations/common'
import { logger } from '@/lib/logger'

interface RouteContext {
  params: Promise<{ id: string }>
}

/**
 * GET /api/admin/attendance/[id]
 * Retrieve single attendance record
 */
export const GET = withErrorHandler(
  withAuth(
    withPermission('attendance:read',
      applyRBACRestrictions(
        { 
          sitePermission: 'attendance:site_only', 
          departmentPermission: 'attendance:department_only' 
        },
        withRateLimit(RateLimits.STANDARD,
          async (context, routeContext) => {
            const { filters } = context as any
            const { id } = await (routeContext as RouteContext).params

            // Validate ID format
            const parseResult = idSchema.safeParse(id)
            if (!parseResult.success) {
              throw new ValidationError('ID tidak valid', {
                errors: parseResult.error.flatten().fieldErrors
              })
            }

            // Fetch attendance with user details
            const attendance = await prisma.attendance.findUnique({
              where: { id: parseResult.data },
              include: {
                user: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    image: true,
                    siteId: true,
                    departmentId: true,
                    departments: { select: { name: true } },
                    sites: { select: { name: true } }
                  }
                }
              }
            })

            if (!attendance) {
              throw new NotFoundError('Data absensi tidak ditemukan')
            }

            // Apply RBAC filtering on the retrieved record
            const recordUser = attendance.user
            if (filters.siteId && recordUser.siteId !== filters.siteId) {
              throw new NotFoundError('Data absensi tidak ditemukan')
            }
            if (filters.departmentId && recordUser.departmentId !== filters.departmentId) {
              throw new NotFoundError('Data absensi tidak ditemukan')
            }

            return apiSuccess(attendance)
          }
        )
      )
    )
  )
)

/**
 * PATCH /api/admin/attendance/[id]
 * Update attendance record (admin correction)
 */
export const PATCH = withErrorHandler(
  withAuth(
    withPermission('attendance:update',
      applyRBACRestrictions(
        { 
          sitePermission: 'attendance:site_only', 
          departmentPermission: 'attendance:department_only' 
        },
        async ({ user, request, filters }, routeContext) => {
          const { id } = await (routeContext as RouteContext).params

          // Validate ID format
          const idParseResult = idSchema.safeParse(id)
          if (!idParseResult.success) {
            throw new ValidationError('ID tidak valid', {
              errors: idParseResult.error.flatten().fieldErrors
            })
          }

          // Parse and validate request body
          const body = await request.json()
          const parseResult = attendanceUpdateSchema.safeParse(body)

          if (!parseResult.success) {
            throw new ValidationError('Data tidak valid', {
              errors: parseResult.error.flatten().fieldErrors
            })
          }

          const { checkIn, checkOut, status, notes } = parseResult.data

          // Fetch existing attendance to get userId and User details
          const existingAttendance = await prisma.attendance.findUnique({
            where: { id: idParseResult.data },
            include: { user: true }
          })

          if (!existingAttendance) {
            throw new NotFoundError('Data absensi tidak ditemukan')
          }

          // Apply RBAC filtering
          const recordUser = existingAttendance.user
          if (filters.siteId && recordUser.siteId !== filters.siteId) {
            throw new NotFoundError('Data absensi tidak ditemukan')
          }
          if (filters.departmentId && recordUser.departmentId !== filters.departmentId) {
            throw new NotFoundError('Data absensi tidak ditemukan')
          }

          // Prepare update data
          const updateData: Prisma.AttendanceUpdateInput = {}
          if (checkIn) updateData.checkIn = new Date(checkIn)
          if (checkOut !== undefined) updateData.checkOut = checkOut ? new Date(checkOut) : null
          if (notes !== undefined) updateData.notes = notes

          // Auto-calculate status if checkIn changes
          if (checkIn && existingAttendance.user.startWorkTime && existingAttendance.user.workingHourMode !== 'FLEXIBLE') {
            const userDetails = existingAttendance.user

            // Fetch Tolerance Setting and Timezone
            const [toleranceSetting, timezoneSetting] = await Promise.all([
              prisma.settings.findFirst({
                where: { key: 'GENERAL_ATTENDANCE_TOLERANCE' }
              }),
              prisma.settings.findFirst({
                where: { key: 'GENERAL_TIMEZONE' }
              })
            ])

            const toleranceMinutes = toleranceSetting?.value ? parseInt(toleranceSetting.value) : 0
            const timezone = timezoneSetting?.value || 'Asia/Jakarta'

            const parts = userDetails.startWorkTime!.split(':')
            const schedHour = Number(parts[0]) || 0
            const schedMinute = Number(parts[1]) || 0

            // 1. Parse the new checkIn time
            const checkInDate = new Date(checkIn)

            // 2. Convert checkIn to Wall Clock Time in Target Timezone
            const checkInInTz = new Date(checkInDate.toLocaleString('en-US', { timeZone: timezone }))

            // 3. Create Schedule for THAT day (in Timezone Context)
            const scheduleTime = new Date(checkInInTz)
            scheduleTime.setHours(schedHour, schedMinute, 0, 0)

            const toleranceMs = toleranceMinutes * 60 * 1000
            const lateThreshold = new Date(scheduleTime.getTime() + toleranceMs)

            // Determine status by comparing "Wall Clock" times
            updateData.status = checkInInTz > lateThreshold ? 'LATE' : 'ON_TIME'
          } else if (status) {
            // If checkIn didn't change (or user has no schedule), allow manual status update
            updateData.status = status
          }

          const updated = await prisma.attendance.update({
            where: { id: idParseResult.data },
            data: updateData,
            include: {
              user: {
                select: {
                  name: true,
                  email: true,
                  image: true,
                  departments: { select: { name: true } },
                  sites: { select: { name: true } }
                }
              }
            }
          })

          // System Log
          try {
            await logger.logActivity({
              action: 'UPDATE',
              subject: 'Attendance',
              userId: user.id,
              details: { id: idParseResult.data, updates: updateData }
            })
          } catch (e) { 
            console.error('Logging failed', e) 
          }

          return apiSuccess(updated, { message: 'Absensi berhasil diperbarui' })
        }
      )
    )
  )
)

/**
 * DELETE /api/admin/attendance/[id]
 * Remove attendance record
 */
export const DELETE = withErrorHandler(
  withAuth(
    withPermission('attendance:delete',
      applyRBACRestrictions(
        { 
          sitePermission: 'attendance:site_only', 
          departmentPermission: 'attendance:department_only' 
        },
        async ({ user, filters }, routeContext) => {
          const { id } = await (routeContext as RouteContext).params

          // Validate ID format
          const parseResult = idSchema.safeParse(id)
          if (!parseResult.success) {
            throw new ValidationError('ID tidak valid', {
              errors: parseResult.error.flatten().fieldErrors
            })
          }

          // Check existence and apply RBAC
          const existing = await prisma.attendance.findUnique({
            where: { id: parseResult.data },
            include: { user: true }
          })

          if (!existing) {
            throw new NotFoundError('Data absensi tidak ditemukan')
          }

          // Apply RBAC filtering
          const recordUser = existing.user
          if (filters.siteId && recordUser.siteId !== filters.siteId) {
            throw new NotFoundError('Data absensi tidak ditemukan')
          }
          if (filters.departmentId && recordUser.departmentId !== filters.departmentId) {
            throw new NotFoundError('Data absensi tidak ditemukan')
          }

          await prisma.attendance.delete({
            where: { id: parseResult.data }
          })

          // System Log
          try {
            await logger.logActivity({
              action: 'DELETE',
              subject: 'Attendance',
              userId: user.id,
              details: { id: parseResult.data }
            })
          } catch (e) { 
            console.error('Logging failed', e) 
          }

          return apiSuccess({ id: parseResult.data }, { message: 'Absensi berhasil dihapus' })
        }
      )
    )
  )
)

import { NextRequest } from 'next/server';
import { prisma } from '@/lib/prisma';
import { WorkOrderRepository } from '@/modules/work-order/repositories/WorkOrderRepository';
import { verifyAuth } from '@/lib/auth';
import { hasPermission } from '@/lib/rbac';
import { workOrderCacheService } from '@/modules/work-order/services/WorkOrderCacheService';
import { apiSuccess, ApiErrors } from '@/lib/api-response';

const workOrderRepo = new WorkOrderRepository(prisma);

/**
 * GET /api/admin/workorders/dashboard
 * 
 * Consolidated dashboard endpoint - combines 6 API calls into 1
 * Reduces network overhead and ensures consistent data snapshot
 */
export async function GET(request: NextRequest) {
    try {
        const user = await verifyAuth(request);
        if (!user) {
            return ApiErrors.unauthorized('Session tidak valid');
        }

        if (!await hasPermission('work_order_dashboard:read')) {
            return ApiErrors.forbidden('Anda tidak memiliki akses untuk melihat dashboard work order');
        }

        const { searchParams } = new URL(request.url);
        const period = searchParams.get('period') || 'all_time';

        // Build access restriction filters
        const { departmentId, siteId, emptyResponse } = buildAccessFilters(user);

        // If user has no access, return empty data
        if (emptyResponse) {
            return apiSuccess({
                ...getEmptyDashboardData(),
                message: "Restricted access: No department/site assigned."
            });
        }

        // PHASE 4: Try to get cached data first
        const cachedData = await workOrderCacheService.getCachedDashboardData(
            user.id,
            period,
            { 
                ...(departmentId ? { departmentId } : {}), 
                ...(siteId ? { siteId } : {}) 
            }
        );

        if (cachedData) {
            return apiSuccess({
                ...(cachedData as any),
                cached: true,
            });
        }

        // Build date filters based on period
        const { dateFrom, dateTo } = buildDateRange(period);

        // Execute all queries in parallel for maximum performance
        const [
            stats,
            recentWorkOrders,
            departmentWorkload,
            topPerformers,
            topAssists,
            issueStats,
            siteStats,
            disconnectionStats,
            responseStats,
            adminKPI
        ] = await Promise.all([
            // Stats
            workOrderRepo.getStatistics({
                ...(departmentId ? { departmentId } : {}),
                ...(siteId ? { siteId } : {})
            }),
            // Recent work orders (optimized - only 5)
            workOrderRepo.getRecentWorkOrders(5, { 
                ...(departmentId ? { departmentId } : {}) 
            }),
            // Department workload
            workOrderRepo.getDepartmentWorkload(departmentId),
            // Top performers
            workOrderRepo.getTopPerformers(5, dateFrom, dateTo, departmentId),
            // Top assists
            workOrderRepo.getTopAssists(5, dateFrom, dateTo, departmentId),
            // Issue statistics
            workOrderRepo.getIssueStatistics(5, dateFrom, dateTo, departmentId, siteId),
            // Site statistics
            workOrderRepo.getSiteStatistics(5, dateFrom, dateTo, departmentId, siteId),
            // Disconnection statistics
            workOrderRepo.getDisconnectionStatistics(dateFrom, dateTo, departmentId, siteId),
            // Response stats
            workOrderRepo.getAdminResponseStats(
                dateFrom || new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Default: last 30 days
                dateTo || new Date(),
                departmentId
            ),
            // Admin KPI stats
            workOrderRepo.getAdminKPIStats(departmentId, siteId),
        ]);

        // Count WO by type (Customer vs Internal) - using isInternal field
        const baseWhere = {
            ...(departmentId ? { departmentId } : {}),
            ...(siteId ? { siteId } : {}),
        };

        const [customerCount, internalCount] = await Promise.all([
            // Customer WO: isInternal = false
            prisma.workOrders.count({
                where: {
                    ...baseWhere,
                    isInternal: false,
                }
            }),
            // Internal WO: isInternal = true
            prisma.workOrders.count({
                where: {
                    ...baseWhere,
                    isInternal: true,
                }
            }),
        ]);

        const woTypeStats = { customer: customerCount, internal: internalCount };

        const dashboardData = {
            stats,
            recentWorkOrders,
            departmentWorkload,
            topPerformers,
            topAssists,
            issueStats,
            siteStats,
            disconnectionStats,
            responseStats,
            adminKPI,
            woTypeStats, // Customer vs Internal count
        };

        // PHASE 4: Cache the result
        await workOrderCacheService.cacheDashboardData(
            user.id,
            period,
            dashboardData,
            { 
                ...(departmentId ? { departmentId } : {}), 
                ...(siteId ? { siteId } : {}) 
            }
        );

        return apiSuccess({
            ...dashboardData,
            cached: false,
        });
    } catch (error) {
        console.error('Error fetching dashboard data:', error);
        return ApiErrors.internalError('Gagal mengambil data dashboard');
    }
}

/**
 * Build date range based on period parameter
 */
function buildDateRange(period: string): { dateFrom?: Date; dateTo?: Date } {
    const now = new Date();
    let dateFrom: Date | undefined;
    let dateTo: Date | undefined = new Date();

    switch (period) {
        case 'daily':
            dateFrom = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            break;
        case 'weekly':
            const firstDay = now.getDate() - now.getDay();
            dateFrom = new Date(now.getFullYear(), now.getMonth(), firstDay);
            break;
        case 'monthly':
            dateFrom = new Date(now.getFullYear(), now.getMonth(), 1);
            break;
        case 'yearly':
            dateFrom = new Date(now.getFullYear(), 0, 1);
            break;
        case 'last_30_days':
            dateFrom = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
            break;
        case 'all_time':
        default:
            // No date filter for all_time
            dateFrom = undefined;
            dateTo = undefined;
            break;
    }

    return { 
        ...(dateFrom ? { dateFrom } : {}),
        ...(dateTo ? { dateTo } : {})
    };
}

/**
 * Build access restriction filters based on user permissions
 */
function buildAccessFilters(user: { id: string; permissions?: string[]; role?: string; departmentId?: string | null; siteId?: string | null }): {
    departmentId?: string;
    siteId?: string;
    emptyResponse: boolean;
} {
    const hasDepartmentRestriction = user.permissions?.includes('workorders:department_only');
    const hasSiteRestriction = user.permissions?.includes('workorders:site_only');
    const isSuperAdmin = user.role === 'SUPER_ADMIN';

    let departmentId: string | undefined;
    let siteId: string | undefined;
    let emptyResponse = false;

    // Department restriction
    if (hasDepartmentRestriction && !isSuperAdmin) {
        if (!user.departmentId) {
            emptyResponse = true;
        } else {
            departmentId = user.departmentId;
        }
    }

    // Site restriction
    if (hasSiteRestriction && !isSuperAdmin) {
        if (!user.siteId) {
            emptyResponse = true;
        } else {
            siteId = user.siteId;
        }
    }

    return { 
        ...(departmentId ? { departmentId } : {}),
        ...(siteId ? { siteId } : {}),
        emptyResponse 
    };
}

/**
 * Return empty dashboard data structure
 */
function getEmptyDashboardData() {
    return {
        stats: {
            total: 0,
            pending: 0,
            assigned: 0,
            inProgress: 0,
            onHold: 0,
            completed: 0,
            verified: 0,
            closed: 0,
            cancelled: 0,
            urgentOpen: 0,
            avgCompletionTimeHours: 0,
            totalCost: 0,
            avgRating: null as number | null,
            totalWithRating: 0
        },
        recentWorkOrders: [] as any[],
        departmentWorkload: [] as any[],
        topPerformers: [] as any[],
        topAssists: [] as any[],
        issueStats: [] as any[],
        siteStats: [] as any[],
        disconnectionStats: [] as any[],
        responseStats: [] as any[],
        adminKPI: {
            pendingVerification: 0,
            avgVerificationTimeMinutes: 0,
            avgOnHoldResponseMinutes: 0,
            verifiedToday: 0,
            verifiedThisWeek: 0,
        },
        woTypeStats: {
            customer: 0,
            internal: 0,
        },
    };
}

import { NextRequest } from 'next/server'
import { prisma } from '@/lib/prisma'
import { bandwidthSchema } from '@/lib/validations/bandwidth'
import { sanitizeInput } from '@/lib/utils/sanitize'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { hasPermission } from '@/lib/rbac'
import { apiSuccess, ApiErrors, ErrorCodes, apiError } from '@/lib/api-response'

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session || !session.user) {
      return ApiErrors.unauthorized('Session tidak valid')
    }

    if (!(await hasPermission("bandwidth:read"))) {
      return ApiErrors.forbidden('Anda tidak memiliki akses untuk melihat bandwidth')
    }

    const { searchParams } = new URL(req.url)
    const status = searchParams.get('status')
    const siteIdParam = searchParams.get('siteId')

    const where: { status?: string; siteId?: string } = {}
    if (status) {
      where.status = status
    }

    const user = session.user as { role: string; siteId?: string; id?: string }
    if (user.role !== 'SUPER_ADMIN' && user.siteId) {
      where.siteId = user.siteId
    } else if (siteIdParam) {
      where.siteId = siteIdParam
    }

    const bandwidths = await prisma.bandwidth.findMany({
      where: where as any,
      orderBy: { createdAt: 'desc' },
      include: {
        _count: {
          select: { hargaPaket: true },
        },
      },
    })

    return apiSuccess(bandwidths)
  } catch (error: unknown) {
    console.error('Error fetching bandwidths:', error)
    const errorMessage = error instanceof Error ? error.message : 'Gagal mengambil data bandwidth'
    return ApiErrors.internalError(errorMessage)
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session || !session.user) {
      return ApiErrors.unauthorized('Session tidak valid')
    }

    if (!(await hasPermission("bandwidth:create"))) {
      return ApiErrors.forbidden('Anda tidak memiliki akses untuk membuat bandwidth')
    }

    const body = await req.json()
    const user = session.user as { role: string; siteId?: string; id?: string }

    let siteIdToSave = body.siteId
    if (user.role !== 'SUPER_ADMIN' && user.siteId) {
      siteIdToSave = user.siteId
    }

    const sanitizedBody: Record<string, string | number | boolean | undefined | null> = {
      name: body.name ? sanitizeInput(body.name) : undefined,
      maxLimitDownload: body.maxLimitDownload ? sanitizeInput(body.maxLimitDownload) : undefined,
      maxLimitUpload: body.maxLimitUpload ? sanitizeInput(body.maxLimitUpload) : undefined,
      burstLimitDownload: body.burstLimitDownload ? sanitizeInput(body.burstLimitDownload) : undefined,
      burstLimitUpload: body.burstLimitUpload ? sanitizeInput(body.burstLimitUpload) : undefined,
      minLimitDownload: body.minLimitDownload ? sanitizeInput(body.minLimitDownload) : undefined,
      minLimitUpload: body.minLimitUpload ? sanitizeInput(body.minLimitUpload) : undefined,
      burstThresholdDownload: body.burstThresholdDownload ? sanitizeInput(body.burstThresholdDownload) : undefined,
      burstThresholdUpload: body.burstThresholdUpload ? sanitizeInput(body.burstThresholdUpload) : undefined,
      burstTimeDownload: body.burstTimeDownload !== undefined && body.burstTimeDownload !== null ? Number(body.burstTimeDownload) : undefined,
      burstTimeUpload: body.burstTimeUpload !== undefined && body.burstTimeUpload !== null ? Number(body.burstTimeUpload) : undefined,
      priority: body.priority !== undefined && body.priority !== null ? Number(body.priority) : undefined,
      description: body.description ? sanitizeInput(body.description) : undefined,
      status: body.status || 'AKTIF',
      siteId: siteIdToSave || null,
    }

    Object.keys(sanitizedBody).forEach(key => {
      if (sanitizedBody[key] === undefined) {
        delete sanitizedBody[key]
      }
    })

    const validation = bandwidthSchema.safeParse(sanitizedBody)
    if (!validation.success) {
      return apiError('Validasi gagal', ErrorCodes.VALIDATION_ERROR, {
        status: 400,
        details: { errors: validation.error.flatten() }
      })
    }

    const dataToCreate: Record<string, string | number | boolean | null> = {}
    Object.keys(validation.data).forEach(key => {
      if (validation.data[key as keyof typeof validation.data] !== undefined) {
        dataToCreate[key] = validation.data[key as keyof typeof validation.data] as string | number | boolean | null
      }
    })

    if (siteIdToSave) {
        dataToCreate.siteId = siteIdToSave
    }

    const { randomUUID } = await import('crypto')

    const bandwidth = await prisma.bandwidth.create({
      data: {
        id: randomUUID(),
        updatedAt: new Date(),
        ...dataToCreate,
      } as any,
    })

    try {
      const { logger } = await import('@/lib/logger')
      await logger.logActivity({
        action: 'CREATE',
        subject: 'Bandwidth',
        ...(session.user.id ? { userId: session.user.id } : {}),
        details: { id: bandwidth.id, name: bandwidth.name, siteId: siteIdToSave }
      })
    } catch (e) {
      console.error('Logging failed', e)
    }

    return apiSuccess(bandwidth, { status: 201, message: 'Bandwidth berhasil dibuat' })
  } catch (error: unknown) {
    console.error('Error creating bandwidth:', error)

    const prismaError = error as { code?: string; message?: string }
    if (prismaError.code === 'P2002') {
      return apiError('Nama bandwidth sudah digunakan', ErrorCodes.CONFLICT, { status: 409 })
    }

    return ApiErrors.internalError(prismaError.message || 'Gagal membuat bandwidth')
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authConfig } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { logger } from '@/lib/logger'
import type { BarangMasuk, BarangKeluar } from '@prisma/client'

async function requireAdmin() {
  const session = await getServerSession(authConfig)
  if (!session) {
    return null
  }
  return session
}

export async function GET(req: NextRequest) {
  const startTime = Date.now()
  try {
    const session = await requireAdmin() as any
    if (!session) {
      logger.warn('Unauthorized access attempt to GET /api/inventory/opname/calculate')
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const searchParams = req.nextUrl.searchParams
    const gudangId = searchParams.get('gudangId')

    if (!gudangId) {
      return NextResponse.json(
        { error: 'Gudang ID harus diisi' },
        { status: 400 }
      )
    }

    try {
      const dbStart = Date.now()

      const barangGudangs = await prisma.barangGudang.findMany({
        where: { gudangId },
        include: {
          barang: {
            select: {
              id: true,
              kode: true,
              nama: true,
              satuan: true,
              createdAt: true
            }
          },
          gudang: {
            select: {
              id: true,
              kode: true,
              nama: true
            }
          }
        },
        orderBy: { barang: { kode: 'asc' } }
      })

      if (barangGudangs.length === 0) {
        logger.dbOperation('findMany', 'BarangGudang+Relations', Date.now() - dbStart)
        return NextResponse.json({
          items: [],
          summary: {
            totalBarang: 0,
            totalStok: 0
          }
        })
      }

      const items = await Promise.all(barangGudangs.map(async (bg) => {
        const stockByCondition = await getStockByCondition(bg.barang.id, bg.gudang.id)

        const stokSistem = bg.stok

        let kondisiBaik = stockByCondition.stokBaru
        const kondisiBekas = stockByCondition.stokBekas
        const kondisiRusak = stockByCondition.stokRusak

        const calculatedTotal = stockByCondition.stokBaru + stockByCondition.stokBekas + stockByCondition.stokRusak
        if (calculatedTotal !== stokSistem && calculatedTotal > 0) {
          const difference = stokSistem - calculatedTotal
          kondisiBaik = Math.max(0, kondisiBaik + difference)
        }

        return {
          barangId: bg.barang.id,
          barangKode: bg.barang.kode,
          barangNama: bg.barang.nama,
          barangSatuan: bg.barang.satuan,
          gudangId: bg.gudang.id,
          gudangNama: bg.gudang.nama,
          stokSistem: stokSistem,
          stokFisik: stokSistem,
          kondisiBaik: kondisiBaik,
          kondisiRusak: kondisiRusak,
          kondisiExpire: kondisiBekas,
          lokasiPenyimpanan: bg.gudang.nama,
          nomorRak: '',
          nomorBox: '',
          pic: 'Gudang',
          suhuPenyimpanan: null as number | null,
          kelembaban: null as number | null,
          tanggalExpire: null as Date | null,
          nomorBatch: '',
          catatanDetail: `Stok sistem: ${stokSistem} (Baru: ${stockByCondition.stokBaru}, Bekas: ${stockByCondition.stokBekas}, Rusak: ${stockByCondition.stokRusak}). Input stok fisik dan breakdown kondisi aktual.`
        }
      }))

      const summary = {
        totalBarang: items.length,
        totalStok: items.reduce((sum, item) => sum + item.stokSistem, 0)
      }

      logger.dbOperation('findMany', 'BarangGudang+Relations', Date.now() - dbStart)

      logger.apiRequest('GET', '/api/inventory/opname/calculate', 200, Date.now() - startTime, {
        userId: session.user.id,
        gudangId,
        totalBarang: items.length,
        totalStok: summary.totalStok
      })

      return NextResponse.json({
        items,
        summary
      })

    } finally {
    }
  } catch (error) {
    logger.error('Error getting stock opname data', error as Error, {
      path: '/api/inventory/opname/calculate',
      method: 'GET',
    })
    return NextResponse.json(
      { error: 'Gagal mengambil data stock opname' },
      { status: 500 }
    )
  }
}

async function getStockByCondition(barangId: string, gudangId: string) {
  const [masukData, keluarData] = await Promise.all([
    prisma.barangMasuk.findMany({
      where: { barangId, gudangId },
      orderBy: { tanggal: 'desc' }
    }),
    prisma.barangKeluar.findMany({
      where: { barangId, gudangId },
      orderBy: { tanggal: 'desc' }
    })
  ])

  let stokBaru = 0
  let stokBekas = 0
  let stokRusak = 0

  masukData.forEach((masuk: BarangMasuk) => {
    switch (masuk.kondisi) {
      case 'BARU':
        stokBaru += masuk.jumlah
        break
      case 'BEKAS':
        stokBekas += masuk.jumlah
        break
      case 'RUSAK':
        stokRusak += masuk.jumlah
        break
      default:
        stokBaru += masuk.jumlah
        break
    }
  })

  keluarData.forEach((keluar: BarangKeluar) => {
    switch (keluar.kondisi) {
      case 'BARU':
        stokBaru = Math.max(0, stokBaru - keluar.jumlah)
        break
      case 'BEKAS':
        stokBekas = Math.max(0, stokBekas - keluar.jumlah)
        break
      case 'RUSAK':
        stokRusak = Math.max(0, stokRusak - keluar.jumlah)
        break
      default:
        stokBaru = Math.max(0, stokBaru - keluar.jumlah)
        break
    }
  })

  return {
    stokBaru,
    stokBekas,
    stokRusak,
    totalStok: stokBaru + stokBekas + stokRusak
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authConfig } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { sendInvoiceSchema } from '@/lib/validations/invoice'

/**
 * @swagger
 * /api/invoices/{id}/send:
 *   post:
 *     summary: Send invoice to customer
 *     description: Mengirim invoice ke pelanggan via email/WhatsApp
 *     tags: [Billing]
 *     security:
 *       - bearerAuth: []
 *       - cookieAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ID
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               recipientEmail:
 *                 type: string
 *                 format: email
 *                 description: Email penerima (opsional, akan menggunakan email pelanggan jika kosong)
 *               recipientPhone:
 *                 type: string
 *                 description: Nomor telepon penerima (opsional, akan menggunakan nomor pelanggan jika kosong)
 *               message:
 *                 type: string
 *                 description: Pesan tambahan (opsional)
 *               sendMethod:
 *                 type: string
 *                 enum: ["EMAIL", "WHATSAPP", "BOTH"]
 *                 default: "EMAIL"
 *                 description: Metode pengiriman
 *     responses:
 *       200:
 *         description: Invoice berhasil dikirim
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 message:
 *                   type: string
 *                   example: "Invoice berhasil dikirim"
 *                 sentVia:
 *                   type: array
 *                   items:
 *                     type: string
 *                   example: ["EMAIL"]
 *       400:
 *         description: Validation error atau invoice tidak dapat dikirim
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       401:
 *         description: Unauthorized
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       404:
 *         description: Invoice tidak ditemukan
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       500:
 *         description: Server error
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 */
export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await getServerSession(authConfig)
    if (!session) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { id } = await params
    // Check if invoice exists
    const invoice = await prisma.invoice.findUnique({
      where: { id },
      include: {
        pelanggan: true,
        invoiceItem: true,
      },
    })

    if (!invoice) {
      return NextResponse.json({ error: 'Invoice tidak ditemukan' }, { status: 404 })
    }

    // Check if invoice is in DRAFT status
    if (invoice.status !== 'DRAFT') {
      return NextResponse.json(
        { error: 'Hanya invoice dengan status DRAFT yang dapat dikirim' },
        { status: 400 }
      )
    }

    const body = await req.json()
    const validation = sendInvoiceSchema.safeParse(body)

    if (!validation.success) {
      return NextResponse.json(
        { error: 'Validation error', details: validation.error.flatten() },
        { status: 400 }
      )
    }

    const { recipientEmail, recipientPhone, message, sendMethod } = validation.data

    // Determine recipients
    const email = recipientEmail || invoice.pelanggan.email
    const phone = recipientPhone || invoice.pelanggan.noTelp

    if (!email && !phone) {
      return NextResponse.json(
        { error: 'Pelanggan tidak memiliki email atau nomor telepon' },
        { status: 400 }
      )
    }

    const sentVia: string[] = []

    // Send via email
    if (sendMethod === 'EMAIL' || sendMethod === 'BOTH') {
      if (!email) {
        return NextResponse.json(
          { error: 'Email pelanggan tidak tersedia' },
          { status: 400 }
        )
      }

      try {
        // TODO: Implement email sending logic
        // const emailResult = await sendInvoiceEmail(invoice, email, message)

        // For now, just log and mark as sent
        console.log(`Sending invoice ${invoice.invoiceNumber} to ${email}`)
        sentVia.push('EMAIL')
      } catch (emailError: unknown) {
        const err = emailError instanceof Error ? emailError : new Error('Unknown error')
        console.error('Error sending email:', err)
        return NextResponse.json(
          { error: `Gagal mengirim email: ${err.message}` },
          { status: 500 }
        )
      }
    }

    // Send via WhatsApp
    if (sendMethod === 'WHATSAPP' || sendMethod === 'BOTH') {
      if (!phone) {
        return NextResponse.json(
          { error: 'Nomor telepon pelanggan tidak tersedia' },
          { status: 400 }
        )
      }

      try {
        // TODO: Implement WhatsApp sending logic
        // const whatsappResult = await sendInvoiceWhatsApp(invoice, phone, message)

        // For now, just log and mark as sent
        console.log(`Sending invoice ${invoice.invoiceNumber} to ${phone} via WhatsApp`)
        sentVia.push('WHATSAPP')
      } catch (whatsappError: unknown) {
        const err = whatsappError instanceof Error ? whatsappError : new Error('Unknown error')
        console.error('Error sending WhatsApp:', err)
        return NextResponse.json(
          { error: `Gagal mengirim WhatsApp: ${err.message}` },
          { status: 500 }
        )
      }
    }

    // Update invoice status to SENT and set sentAt
    await prisma.invoice.update({
      where: { id },
      data: {
        status: 'SENT',
        sentAt: new Date(),
      },
    })

    return NextResponse.json({
      message: 'Invoice berhasil dikirim',
      sentVia,
    })
  } catch (error: unknown) {
    const err = error instanceof Error ? error : new Error('Unknown error')
    console.error('Error sending invoice:', err)
    return NextResponse.json(
      { error: err.message || 'Internal Server Error' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { verifyAuth } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

interface GeminiResponse {
  candidates?: Array<{
    content?: {
      parts?: Array<{
        text?: string;
      }>;
    };
  }>;
  error?: {
    message?: string;
  };
}

interface KtpError {
  model: string;
  status?: number;
  message: string;
  details?: unknown;
}

/**
 * POST /api/ktp-ocr
 * Ekstraksi data KTP menggunakan Google Gemini API
 */
export async function POST(req: NextRequest) {
  try {
    // Cek autentikasi (Support Mobile & Web)
    const session = await verifyAuth(req)
    if (!session) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Ambil API Key dari database atau environment variable
    let apiKey = process.env.GOOGLE_GEMINI_API_KEY

    // Cek di database terlebih dahulu
    const settings = await prisma.settings.findUnique({
      where: { key: 'GOOGLE_GEMINI_API_KEY' },
    })

    if (settings?.value) {
      apiKey = settings.value
    }

    // Cek API Key
    if (!apiKey) {
      return NextResponse.json(
        { error: 'Google Gemini API Key tidak dikonfigurasi. Silakan atur di menu Pengaturan > API' },
        { status: 500 }
      )
    }

    const formData = await req.formData()
    const file = formData.get('file') as File

    if (!file) {
      return NextResponse.json(
        { error: 'File tidak ditemukan' },
        { status: 400 }
      )
    }

    // Validasi tipe file
    if (!file.type.startsWith('image/')) {
      return NextResponse.json(
        { error: 'File harus berupa gambar (PNG, JPG, JPEG)' },
        { status: 400 }
      )
    }

    // Convert file ke base64
    const arrayBuffer = await file.arrayBuffer()
    const buffer = Buffer.from(arrayBuffer)
    const base64ImageData = buffer.toString('base64')

    // Schema untuk ekstraksi data KTP
    const ktpSchema = {
      type: 'OBJECT',
      properties: {
        nik: { type: 'STRING', description: 'Nomor Induk Kependudukan (16 digit)' },
        nama: { type: 'STRING', description: 'Nama Lengkap' },
        tempat_lahir: { type: 'STRING', description: 'Kota Tempat Lahir' },
        tanggal_lahir: { type: 'STRING', description: 'Tanggal Lahir (DD-MM-YYYY)' },
        jenis_kelamin: { type: 'STRING', description: 'Jenis Kelamin' },
        alamat_jalan: { type: 'STRING', description: 'Nama jalan, kampung, atau dusun dari alamat' },
        rt_rw: { type: 'STRING', description: 'Nomor RT dan RW dari alamat, format: 001/002' },
        kel_desa: { type: 'STRING', description: 'Nama Kelurahan atau Desa dari alamat' },
        kecamatan: { type: 'STRING', description: 'Nama Kecamatan dari alamat' },
        provinsi: { type: 'STRING', description: 'Nama Provinsi dari alamat' },
        agama: { type: 'STRING', description: 'Agama' },
        status_perkawinan: { type: 'STRING', description: 'Status Perkawinan' },
        pekerjaan: { type: 'STRING', description: 'Pekerjaan' },
        kewarganegaraan: { type: 'STRING', description: 'Kewarganegaraan' },
        berlaku_hingga: { type: 'STRING', description: 'Masa Berlaku (SEUMUR HIDUP atau tanggal)' },
        tempat_dikeluarkan: { type: 'STRING', description: 'Kota/Kabupaten tempat KTP dikeluarkan, biasanya di kanan bawah' },
        tanggal_dikeluarkan: { type: 'STRING', description: 'Tanggal KTP dikeluarkan (DD-MM-YYYY), biasanya di kanan bawah' },
      },
    }

    // Panggil Google Gemini API - mengikuti implementasi yang berhasil
    // Gunakan model yang dikonfirmasi tersedia untuk Key ini
    const models = ['gemini-2.5-flash', 'gemini-2.0-flash-001', 'gemini-flash-latest']
    let lastError: KtpError | null = null

    // Tentukan mimeType - mengikuti implementasi yang berhasil
    // Default ke image/jpeg seperti di referensi HTML
    let mimeType = 'image/jpeg'
    if (file.type === 'image/png') {
      mimeType = 'image/png'
    } else if (file.type === 'image/jpeg' || file.type === 'image/jpg') {
      mimeType = 'image/jpeg'
    }

    for (const model of models) {
      const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`

      const payload = {
        contents: [
          {
            parts: [
              {
                text: 'Analisis gambar KTP Indonesia ini dengan saksama. Ekstrak semua informasi secara detail sesuai skema JSON. Sangat PENTING: Kembalikan SEMUA medan (field) dalam skema, walaupun tidak dapat ditemukan pada gambar. Jika sebuah medan tidak ditemukan, kembalikan sebagai string kosong (""). Jangan menghilangkan medan apa pun dari respons JSON. Pecah alamat menjadi alamat_jalan, rt_rw, kel_desa, dan kecamatan. Pastikan format tanggal adalah DD-MM-YYYY. Jika bagian alamat tidak terbaca, gunakan konteks dari tempat_dikeluarkan untuk menyimpulkan informasi yang mungkin.',
              },
              {
                inlineData: {
                  mimeType: mimeType,
                  data: base64ImageData,
                },
              },
            ],
          },
        ],
        generationConfig: {
          responseMimeType: 'application/json',
          responseSchema: ktpSchema,
        },
      }

      console.log(`Trying model: ${model}`)
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!response.ok) {
        let errorBody: GeminiResponse = {}
        let errorMessage: string = response.statusText

        try {
          const text = await response.text()
          if (text) {
            errorBody = JSON.parse(text)
            const bodyMessage = errorBody.error?.message || errorBody.error
            if (typeof bodyMessage === 'string') {
                errorMessage = bodyMessage
            } else if (bodyMessage && typeof bodyMessage === 'object' && 'message' in bodyMessage) {
                errorMessage = (bodyMessage as any).message || errorMessage
            }
          }
        } catch (e) {
          console.error('Failed to parse error response:', e)
        }

        console.error(`API Error Response (${model}):`, {
          status: response.status,
          statusText: response.statusText,
          errorBody,
        })

        lastError = {
          model,
          status: response.status,
          message: errorMessage,
          details: errorBody,
        }

        // Jika ini bukan model terakhir, coba model berikutnya
        if (model !== models[models.length - 1]) {
          console.log(`Model ${model} failed, trying next model...`)
          continue
        }

        // Jika semua model gagal, return error
        return NextResponse.json(
          {
            error: `Error API (${response.status}): ${errorMessage}`,
            details: errorBody,
            triedModels: models,
          },
          { status: response.status }
        )
      }

      // Jika response OK, parse dan return
      let result: GeminiResponse
      try {
        const text = await response.text()
        if (!text) {
          throw new Error('Response body is empty')
        }
        result = JSON.parse(text)
      } catch (e: unknown) {
        const errorMessage = e instanceof Error ? e.message : String(e)
        console.error('Failed to parse API response:', e)
        // Jika ini bukan model terakhir, coba model berikutnya
        if (model !== models[models.length - 1]) {
          lastError = { model, message: errorMessage }
          continue
        }
        return NextResponse.json(
          { error: `Gagal memparse respons API: ${errorMessage}` },
          { status: 500 }
        )
      }

      console.log(`API Response structure (${model}):`, {
        hasCandidates: !!result.candidates,
        candidatesLength: result.candidates?.length,
        firstCandidate: result.candidates?.[0],
        fullResult: JSON.stringify(result).substring(0, 500),
      })

      if (result.candidates && result.candidates[0]?.content?.parts?.[0]?.text) {
        try {
          const ktpData = JSON.parse(result.candidates[0].content.parts[0].text)
          console.log(`Successfully extracted KTP data using model: ${model}`)
          return NextResponse.json({ data: ktpData })
        } catch (e: unknown) {
          const errorMessage = e instanceof Error ? e.message : String(e)
          console.error('Failed to parse KTP data:', e)
          console.error('Raw text:', result.candidates[0].content.parts[0].text)
          // Jika ini bukan model terakhir, coba model berikutnya
          if (model !== models[models.length - 1]) {
            lastError = { model, message: `Failed to parse KTP data: ${errorMessage}` }
            continue
          }
          return NextResponse.json(
            { error: `Gagal memparse data KTP: ${errorMessage}` },
            { status: 500 }
          )
        }
      } else {
        console.error(`Invalid API response structure (${model}):`, JSON.stringify(result, null, 2))
        // Jika ini bukan model terakhir, coba model berikutnya
        if (model !== models[models.length - 1]) {
          lastError = { 
            model, 
            message: 'Struktur respons API tidak valid atau tidak berisi teks.',
            details: result,
          }
          continue
        }
        return NextResponse.json(
          { 
            error: 'Struktur respons API tidak valid atau tidak berisi teks.',
            details: result,
          },
          { status: 500 }
        )
      }
    }

    // Jika semua model gagal
    return NextResponse.json(
      {
        error: 'Semua model gagal memproses KTP',
        lastError,
        triedModels: models,
      },
      { status: 500 }
    )
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'Terjadi kesalahan saat memproses KTP'
    console.error('Error processing KTP OCR:', error)
    return NextResponse.json(
      { error: errorMessage },
      { status: 500 }
    )
  }
}

