 *                   type: integer
 *                   description: Created router ID
 *                   example: 1
 *       400:
 *         $ref: '#/components/responses/ValidationError'
 *       401:
 *         $ref: '#/components/responses/Unauthorized'
 *       409:
 *         description: IP address already exists or conflict occurred
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 error:
 *                   type: string
 *                   example: "IP Address sudah terpakai atau terjadi kesalahan"
 *       500:
 *         $ref: '#/components/responses/Error'
 */
export async function GET(req: NextRequest) {
  try {
    // Cek autentikasi admin menggunakan fungsi terpusat
    const session = await getServerSession(authOptions)
    if (!session || !session.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (!(await hasPermission("mikrotik:read"))) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    }

    const { searchParams } = new URL(req.url)
    const page = parseInt(searchParams.get('page') || '1')
    const limit = parseInt(searchParams.get('limit') || '10')
    const search = searchParams.get('search') || undefined

    const routerRepository = getMikroTikRouterRepository()

    // RBAC: Check site restrictions
    let siteIdFilter: string | undefined = undefined
    if ((await hasPermission("mikrotik:site_only")) && session.user.role !== 'SUPER_ADMIN') {
        const userSiteId = (session.user as { siteId?: string }).siteId
        if (!userSiteId) {
             // User has site restriction but no site assigned, return empty or error?
             // Returning empty list is safer
             return NextResponse.json({
                routers: [],
                total: 0,
                page,
                limit,
                totalPages: 0
             })
        }
        siteIdFilter = userSiteId
    }

    // Use findWithFilters if pagination params are present, otherwise findAll for backward compatibility if needed
    // But better to always use paginated response for consistency on this route
    const filters: Record<string, string | undefined> = {}
    if (search) filters.search = search
    if (siteIdFilter) filters.siteId = siteIdFilter

    const result = await routerRepository.findWithFilters(
      filters,
      { page, limit }
    )

    return NextResponse.json(result)
  } catch (error: unknown) {
    console.error('Error fetching MikroTik Routers:', error)
    const errorMessage = error instanceof Error ? error.message : String(error)
    return NextResponse.json(
      { error: errorMessage || 'Gagal memuat data Router', routers: [], total: 0, page: 1, limit: 10, totalPages: 0 },
      { status: 500 }
    )
  }
}

export async function POST(req: NextRequest) {
  // Cek autentikasi admin menggunakan fungsi terpusat
  const session = await getServerSession(authOptions)
  if (!session || !session.user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  if (!(await hasPermission("mikrotik:create"))) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }
  const body = await req.json()
  const parsed = mikrotikRouterCreateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }
  const {
    name,
    ipAddress,
    timezone,
    apiPort,
    apiUsername,
    apiPassword,
    authPort,
    accountingPort,
    secretRadius,
    isolirUrl,
    description,
    siteId,
  } = parsed.data

  // RBAC: Check site restrictions for creation
  let finalSiteId = siteId
  if ((await hasPermission("mikrotik:site_only")) && session.user.role !== 'SUPER_ADMIN') {
       const userSiteId = (session.user as { siteId?: string }).siteId
       if (!userSiteId) {
           return NextResponse.json({ error: 'User tidak memiliki akses site untuk membuat router' }, { status: 403 })
       }
       finalSiteId = userSiteId
  }
  try {
    const routerRepository = getMikroTikRouterRepository()
    // 3. Create Router (Repository)
    // NAS sync happens inside Repository
    const createData: Record<string, string | number | undefined> = {
      name,
      ipAddress,
      apiPort: Number(apiPort),
      apiUsername,
      apiPassword,
      authPort: Number(authPort),
      accountingPort: Number(accountingPort),
      secretRadius,
    }
    if (timezone) createData.timezone = timezone
    if (isolirUrl) createData.isolirUrl = isolirUrl
    if (description) createData.description = description
    if (finalSiteId) createData.siteId = finalSiteId

    const router = await routerRepository.create(createData as any)

    // 4. Auto Provisioning (Optional)
    let provisioningResult = { success: true, logs: [] as string[] };

    if (body.autoConfigure) {
      console.log('Starting Auto Provisioning...');
      try {
        // Wrap import in try-catch to prevent module loading errors from crashing the request
        const serviceModule = await import('@/modules/network/services/MikroTikProvisioningService');
        if (serviceModule && serviceModule.MikroTikProvisioningService) {
            const { MikroTikProvisioningService } = serviceModule;
            const provisioningService = new MikroTikProvisioningService();

            provisioningResult = await provisioningService.provisionRadius(
            {
                ip: ipAddress,
                port: Number(apiPort),
                username: apiUsername,
                password: apiPassword,
            },
            null, // Auto-detect IP
            secretRadius,
            isolirUrl // Pass optional Isolir URL
            );

            if (!provisioningResult.success) {
                console.warn(`Router created but provisioning failed: ${provisioningResult.logs.join(', ')}`);
            }

            // 5. Auto Create API User (setelah provisioning berhasil)
            console.log('Creating API User...');
            const apiUserResult = await provisioningService.createApiUser({
                ip: ipAddress,
                port: Number(apiPort),
                username: apiUsername,
                password: apiPassword,
            });

            if (apiUserResult.success && apiUserResult.username && apiUserResult.password) {
                // Update database dengan generated credentials
                const { prisma } = await import('@/lib/prisma');
                await prisma.mikroTikRouter.update({
                    where: { id: router.id },
                    data: {
                        apiUsernameGenerated: apiUserResult.username,
                        apiPasswordGenerated: apiUserResult.password,
                    }
                });
                console.log(`API User created and saved: ${apiUserResult.username}`);
            } else {
                console.warn(`API User creation failed: ${apiUserResult.logs.join(', ')}`);
            }
        } else {
            console.error('Failed to load MikroTikProvisioningService module');
            provisioningResult = { success: false, logs: ['Internal Error: Could not load provisioning service'] };
        }
      } catch (e: unknown) {
        console.error('Provisioning CRITICAL error:', e);
        // Do not fail the request if provisioning fails, just log it.
        // We still want to return the success response for the Router creation.
        provisioningResult = { success: false, logs: [e instanceof Error ? e.message : 'Unknown provisioning error'] };
      }
    }

    // Trigger initial status check (running in background so response isn't delayed too much,
    // or await it if fast enough. 5s timeout is acceptable for "Add" action)
    try {
      const { checkSingleMikroTikRouterStatus } = await import('@/modules/network/services/mikrotik-ping-check')
      await checkSingleMikroTikRouterStatus(router.id)
    } catch (err) {
      console.error('Failed to perform initial router check:', err)
    }

    // System Log
    try {
      const { logger } = await import('@/lib/logger')
      await logger.logActivity({
        action: 'CREATE',
        subject: 'MikroTik Router',
        userId: session.user.id!,
        details: { id: router.id, name: name, ip: ipAddress }
      })
    } catch (e) {
      console.error('Logging failed', e)
    }

    return NextResponse.json({ id: router.id })
  } catch (_e: unknown) {
    return NextResponse.json({ error: 'IP Address sudah terpakai atau terjadi kesalahan' }, { status: 409 })
  }
}

import { NextResponse } from 'next/server'
import { LeaveRepository } from '@/modules/attendance/repositories/LeaveRepository'
import { LeaveBalanceRepository } from '@/modules/attendance/repositories/LeaveBalanceRepository'
import { verifyMobileToken } from '@/lib/mobile-auth'
import { LeaveType, LeaveStatus } from '@prisma/client'
import { createNotification } from '@/modules/notification/services/NotificationService'
import { prisma } from '@/lib/prisma'
import { convertAndSaveBase64 } from '@/lib/utils/image-upload'

const repo = new LeaveRepository()
const leaveBalanceRepo = new LeaveBalanceRepository()

export async function GET(request: Request) {
    try {
        const authHeader = request.headers.get('authorization')
        const token = authHeader?.replace('Bearer ', '')

        if (!token) {
            return NextResponse.json({ error: 'Token required' }, { status: 401 })
        }

        const user = await verifyMobileToken(token) as any;
        if (!user) {
            return NextResponse.json({ error: 'Invalid token' }, { status: 401 })
        }

        const leaves = await repo.findAll({ userId: user.id })
        return NextResponse.json({ success: true, data: leaves })
    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        return NextResponse.json({ error: errorMessage }, { status: 500 })
    }
}

export async function POST(request: Request) {
    try {
        const authHeader = request.headers.get('authorization')
        const token = authHeader?.replace('Bearer ', '')

        if (!token) {
            return NextResponse.json({ error: 'Token required' }, { status: 401 })
        }

        const user = await verifyMobileToken(token) as any;
        if (!user) {
            return NextResponse.json({ error: 'Invalid token' }, { status: 401 })
        }

        const body = await request.json()
        const { type, startDate, endDate, reason, photos, replacementDate } = body

        if (!type || !startDate || !endDate || !reason) {
            return NextResponse.json({ error: 'Missing required fields' }, { status: 400 })
        }

        // Calculate leave days
        const start = new Date(startDate)
        const end = new Date(endDate)
        const leaveDays = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1
        const currentYear = start.getFullYear()

        // Check user's working hour mode - FLEXIBLE users don't have leave quotas
        const userData = await prisma.user.findUnique({
            where: { id: user.id },
            select: { workingHourMode: true, workDays: true, name: true }
        })

        // Validate leave quota (skip for FLEXIBLE users and TUKAR_LIBUR type)
        if (userData?.workingHourMode !== 'FLEXIBLE' && type !== 'TUKAR_LIBUR') {
            const hasEnough = await leaveBalanceRepo.hasEnoughDays(user.id, currentYear, type as LeaveType, leaveDays)
            if (!hasEnough) {
                const remaining = await leaveBalanceRepo.getRemainingDays(user.id, currentYear, type as LeaveType)
                return NextResponse.json({ 
                    error: `Kuota ${type} tidak cukup. Sisa: ${remaining} hari, Dibutuhkan: ${leaveDays} hari.`
                }, { status: 400 })
            }
        }

        // Validate attachment for non-CUTI types
        if (type !== 'CUTI' && type !== 'TUKAR_LIBUR' && (!photos || photos.length === 0)) {
            return NextResponse.json({ error: 'Foto bukti wajib diupload' }, { status: 400 })
        }

        // Validate replacementDate for TUKAR_LIBUR
        if (type === 'TUKAR_LIBUR') {
            if (!replacementDate) {
                return NextResponse.json({ error: 'Tanggal pengganti wajib diisi untuk Tukar Libur' }, { status: 400 })
            }

            if (userData?.workDays) {
                const workDays = userData.workDays.split(',').map(d => d.trim());
                const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

                const start = new Date(startDate);
                const replacement = new Date(replacementDate);

                const startDayName = days[start.getDay()];
                const replacementDayName = days[replacement.getDay()];

                // Helper to format date for comparison YYYY-MM-DD
                const formatDate = (date: Date) => date.toISOString().split('T')[0];

                // 1. Validate Start Date (Must be a Work Day)
                if (!startDayName || !workDays.includes(startDayName)) {
                     return NextResponse.json({
                        error: `Tanggal izin (${startDate}) harus merupakan Hari Kerja.`
                    }, { status: 400 })
                }

                // 2. Validate Replacement Date (Must be Off Day OR Holiday)
                // Check if it's an Off Day
                const isOffDay = replacementDayName ? !workDays.includes(replacementDayName) : false;

                // Check if it's a Holiday
                const formattedReplacementDate = formatDate(replacement);
                const holiday = formattedReplacementDate ? await prisma.holiday.findUnique({
                    where: { date: new Date(formattedReplacementDate) }
                }) : null;

                if (!isOffDay && !holiday) {
                     return NextResponse.json({ 
                        error: `Tanggal pengganti (${replacementDate}) harus merupakan Hari Libur atau Tanggal Merah.` 
                    }, { status: 400 })
                }
            }
        }

        // Convert base64 photos to URLs
        const attachments: string[] = []
        if (photos && photos.length > 0) {
            for (let i = 0; i < photos.length; i++) {
                const photo = photos[i]

                // If it's already a URL (from SyncService upload), just use it
                if (photo.startsWith('http') || photo.startsWith('/uploads')) {
                    attachments.push(photo);
                    continue;
                }

                // Otherwise treat as Base64
                const timestamp = Date.now()
                const fileName = `leave_${user.id}_${timestamp}_${i}`
                const uploadDir = 'public/uploads/employee-leave'
                const url = await convertAndSaveBase64(
                    photo,
                    uploadDir,
                    fileName,
                    'employee-leave'  // uploadType for R2
                )
                if (url) attachments.push(url)
            }
        }

        const createData: Record<string, unknown> = {
            user: { connect: { id: user.id } },
            type: type as LeaveType,
            startDate: new Date(startDate),
            endDate: new Date(endDate),
            replacementDate: replacementDate ? new Date(replacementDate) : null,
            reason,
            attachments: attachments,
            status: LeaveStatus.PENDING
        }

        if (attachments.length > 0) {
            createData.attachmentUrl = attachments[0]
        }

        const requestData = await repo.create(createData as any)

        // Notify Admins
        try {
            const userData = await prisma.user.findUnique({ where: { id: user.id }, select: { name: true } })
            const admins = await prisma.user.findMany({
                where: {
                    isActive: true, // Only notify active admins
                    OR: [
                        { role: { name: { in: ['SUPER_ADMIN', 'Super Admin'] } } },
                        {
                            role: {
                                permission: {
                                    some: {
                                        resource: { in: ['attendance', 'kehadiran'] },
                                        action: 'update'
                                    }
                                }
                            }
                        }
                    ]
                },
                select: { id: true }
            })

            for (const admin of admins) {
                await createNotification({
                    type: 'SYSTEM',
                    priority: 'NORMAL',
                    title: '📋 Pengajuan Izin Baru (Mobile)',
                    message: `${userData?.name} mengajukan ${type}: ${reason}`,
                    link: '/admin/kehadiran/izin',
                    userId: admin.id,
                    sourceType: 'LEAVE',
                    sourceId: requestData.id
                })
            }
        } catch (error) {
            console.error('Failed to notify admins', error)
        }

        return NextResponse.json({ success: true, data: requestData }, { status: 201 })
    } catch (error: unknown) {
        console.error('Leave request error:', error)
        return NextResponse.json({ error: error instanceof Error ? error.message : 'Unknown error' }, { status: 500 })
    }
}

import { NextRequest, NextResponse } from 'next/server'
import { verifyMobileToken } from '@/lib/mobile-auth'
import { LocationTrackingService } from '@/modules/attendance/services/LocationTrackingService'

/**
 * POST /api/mobile/location
 * Menerima update lokasi dari mobile app
 * Hanya menyimpan jika user sedang dalam status check-in
 */
export async function POST(request: NextRequest) {
    const timestamp = new Date().toISOString()
    try {
        const authHeader = request.headers.get('Authorization')
        if (!authHeader || !authHeader.startsWith('Bearer ')) {
            console.log(`[API][${timestamp}] Location update: Missing token`)
            return NextResponse.json({ error: 'Missing or invalid token' }, { status: 401 })
        }

        const token = authHeader.split(" ")[1]
        if (!token) {
            return NextResponse.json({ error: "Token not provided" }, { status: 401 })
        }
        const payload = await verifyMobileToken(token)
        if (!payload) {
            console.log(`[API][${timestamp}] Location update: Invalid token`)
            return NextResponse.json({ error: 'Invalid or expired token' }, { status: 401 })
        }

        const userId = payload.id as string
        const body = await request.json()

        console.log(`[API][${timestamp}] ========== LOCATION UPDATE ==========`)
        console.log(`[API][${timestamp}] User ID: ${userId}`)
        console.log(`[API][${timestamp}] Data received:`, JSON.stringify(body))

        const locationService = new LocationTrackingService()

        // Cek apakah user sedang check-in
        const isCheckedIn = await locationService.isUserCurrentlyCheckedIn(userId)
        console.log(`[API][${timestamp}] User check-in status: ${isCheckedIn}`)

        if (!isCheckedIn) {
            console.log(`[API][${timestamp}] ❌ User not checked in, stopping tracking`)
            return NextResponse.json({ 
                success: false, 
                message: 'User is not currently checked in',
                shouldStopTracking: true 
            })
        }

        // Handle batch locations (offline sync)
        if (Array.isArray(body.locations)) {
            console.log(`[API][${timestamp}] Processing batch of ${body.locations.length} locations`)
            const count = await locationService.saveLocations(userId, body.locations.map((loc: Record<string, any>) => ({
                latitude: loc.latitude,
                longitude: loc.longitude,
                accuracy: loc.accuracy,
                altitude: loc.altitude,
                speed: loc.speed,
                heading: loc.heading,
                batteryLevel: loc.batteryLevel,
                isMoving: loc.isMoving,
                recordedAt: loc.recordedAt ? new Date(loc.recordedAt as string) : new Date()
            })))

            console.log(`[API][${timestamp}] ✅ Batch saved: ${count} locations`)
            return NextResponse.json({ 
                success: true, 
                message: `Saved ${count} locations`,
                count
            })
        }

        // Handle single location
        console.log(`[API][${timestamp}] Saving single location...`)
        await locationService.saveLocation(userId, {
            latitude: body.latitude,
            longitude: body.longitude,
            accuracy: body.accuracy,
            altitude: body.altitude,
            speed: body.speed,
            heading: body.heading,
            batteryLevel: body.batteryLevel,
            isMoving: body.isMoving,
            recordedAt: body.recordedAt ? new Date(body.recordedAt) : new Date()
        })

        console.log(`[API][${timestamp}] ✅ Single location saved successfully`)
        console.log(`[API][${timestamp}] ==========================================`)
        return NextResponse.json({ success: true, message: 'Location saved' })

    } catch (error: unknown) {
        console.error(`[API][${timestamp}] ❌ Error saving location:`, error)
        return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { verifyMobileToken } from '@/lib/mobile-auth';
import { prisma } from '@/lib/prisma';
import { WorkOrderRepository } from '@/modules/work-order/repositories/WorkOrderRepository';
import { socketEmitter } from '@/lib/websocket/emitter';
import { notifyAdminsAboutMobileAction } from '@/modules/notification';

// PATCH - Update Task Status
export async function PATCH(
    request: NextRequest,
    props: { params: Promise<{ id: string }> }
) {
    const params = await props.params;
    try {
        const authHeader = request.headers.get('Authorization');
        if (!authHeader?.startsWith('Bearer ')) {
            return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
        }
        const token = authHeader.split(' ')[1];
        if (!token) {
            return NextResponse.json({ error: 'Invalid token format' }, { status: 401 });
        }

        const user = await verifyMobileToken(token) as any;
        if (!user) {
            return NextResponse.json({ error: 'Invalid token' }, { status: 401 });
        }

        const workOrderId = params.id;
        const body = await request.json();
        const { taskId, isCompleted } = body;

        if (!taskId) {
            return NextResponse.json({ error: 'Task ID required' }, { status: 400 });
        }

        const repository = new WorkOrderRepository(prisma);

        // Get task info before update for notification message
        const task = await prisma.workOrderTasks.findUnique({
            where: { id: taskId },
            select: { title: true }
        });

        // Verify user is assigned to this WO or has permission
        // For simplicity, we assume if they can see the WO, they can update tasks (since they are assigned)
        // Ideally checking assignment here would be better but skipping for MVP speed

        await repository.updateTask(taskId, {
            status: isCompleted ? 'COMPLETED' : 'PENDING',
            completedById: isCompleted ? user.id : undefined
        });

        // Fetch updated work order for socket payload
        const updatedWO = await repository.findById(workOrderId);

        if (updatedWO) {
            // Emit socket event for real-time update
            socketEmitter.updateWorkOrder(updatedWO);

            // Notify admins about task update
            await notifyAdminsAboutMobileAction({
                workOrderId,
                workOrderNumber: updatedWO.workOrderNumber,
                title: updatedWO.title,
                actionType: 'NOTE',
                actionMessage: isCompleted
                    ? `Menyelesaikan task: ${task?.title || 'Unknown'}`
                    : `Membatalkan task: ${task?.title || 'Unknown'}`,
                triggeredByUserId: user.id,
                triggeredByName: user.name || 'Unknown',
                ...(updatedWO.departmentId && { departmentId: updatedWO.departmentId }),
                ...(updatedWO.siteId && { siteId: updatedWO.siteId })
            }).catch(err => console.error('[TaskNotify] Error:', err));
        }

        // Fetch updated WO to return? Or just success
        return NextResponse.json({
            success: true,
            message: 'Task updated'
        });

    } catch (error) {
        console.error('Task Update Error:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authConfig } from '@/lib/auth'
import { configurationRestoreCreateSchema } from '@/lib/validations/device-backup'
import { prisma } from '@/lib/prisma'

async function requireAdmin() {
  const session = await getServerSession(authConfig)
  if (!session) {
    return null
  }
  return session
}

/**
 * @swagger
 * /api/network/backups/{id}/restore:
 *   post:
 *     summary: Restore configuration from backup
 *     description: Memulih konfigurasi dari backup
 *     tags: [Configuration Restore]
 *     security:
 *       - bearerAuth: []
 *       - cookieAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Backup ID
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - deviceId
 *               - deviceType
 *               - backupId
 *               - restoreName
 *             properties:
 *               deviceId:
 *                 type: string
 *                 description: Device ID
 *               deviceType:
 *                 type: string
 *                 enum: [OLT, MIKROTIK, ONU]
 *                 description: Device type
 *               backupId:
 *                 type: string
 *                 description: Backup ID to restore from
 *               restoreName:
 *                 type: string
 *                 description: Restore name
 *               description:
 *                 type: string
 *                 description: Restore description
 *               restoreMethod:
 *                 type: string
 *                 description: Restore method (SNMP, API, SSH, TELNET)
 *               scheduledAt:
 *                 type: string
 *                 format: date-time
 *                 description: Scheduled restore time
 *               rollbackEnabled:
 *                 type: boolean
 *                 default: false
 *                 description: Whether rollback is enabled
 *     responses:
 *       201:
 *         description: Configuration restore initiated successfully
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 id:
 *                   type: string
 *       400:
 *         description: Validation error
 *       401:
 *         description: Unauthorized
 *       404:
 *         description: Backup not found
 *       500:
 *         description: Server error
 */
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
): Promise<NextResponse> {
  try {
    const session = await requireAdmin()
    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { id } = await params
    const json = await req.json()
    const parsed = configurationRestoreCreateSchema.safeParse(json)

    if (!parsed.success) {
      return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
    }

    const data = parsed.data

    // Verify backup exists
    try {
      const backup = await prisma.deviceBackups.findUnique({
          where: { id },
      })

      if (!backup) {
          return NextResponse.json({ error: 'Backup tidak ditemukan' }, { status: 404 })
      }

      const result = await prisma.configurationRestores.create({
        data: {
          deviceId: data.deviceId,
          deviceType: data.deviceType,
          backupId: id,
          restoreName: data.restoreName,
          description: data.description,
          restoreMethod: data.restoreMethod,
          scheduledAt: data.scheduledAt ? new Date(data.scheduledAt) : undefined,
          rollbackEnabled: data.rollbackEnabled || false,
          createdBy: (session as { user?: { id?: string } }).user?.id,
        } as any,
      })

      return NextResponse.json({ id: result.id }, { status: 201 })
    } catch (prismaError: unknown) {
      // Handle case where model doesn't exist yet
      if (prismaError instanceof Error && (prismaError as unknown as Record<string, unknown>).code === 'P2021') {
        return NextResponse.json(
          { error: 'Configuration restore will be available after database migration' },
          { status: 503 }
        )
      }
      throw prismaError
    }
  } catch (error: unknown) {
    console.error('Error creating configuration restore:', error)
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Gagal membuat restore konfigurasi' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { profilePPPSchema } from '@/lib/validations/profileppp'
import { sanitizeInput } from '@/lib/utils/sanitize'
import { createPPPProfileInMikroTik } from '@/modules/network/services/mikrotik-ppp-profile'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { hasPermission } from '@/lib/rbac'
import { randomUUID } from 'crypto'
import { Prisma } from '@prisma/client'

/**
 * GET /api/profileppps
 * Mendapatkan semua data Profile PPP
 * 
 * @swagger
 * /api/profileppps:
 *   get:
 *     tags: [ProfilePPP]
 *     summary: Mendapatkan semua data profile PPP
 *     responses:
 *       200:
 *         description: List profile PPP
 */
export async function GET(req: NextRequest) {
  try {
    // Cek autentikasi menggunakan fungsi terpusat
    const session = await getServerSession(authOptions)
    if (!session || !session.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (!(await hasPermission("profileppp:read"))) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    }

    const { searchParams } = new URL(req.url)
    const status = searchParams.get('status')
    const siteIdParam = searchParams.get('siteId')

    const where: Prisma.ProfilePPPWhereInput = {}
    if (status) {
      where.status = status as 'AKTIF' | 'NONAKTIF'
    }

    // User restriction logic
    if (session.user.role !== "SUPER_ADMIN") {
      // For non-super admins, restrict to their assigned site
      if (session.user.siteId) {
        where.siteId = session.user.siteId
      }
    } else if (siteIdParam) {
      // For super admins, allow filtering if param is provided
      where.siteId = siteIdParam
    }

    const profilePPPs = await prisma.profilePPP.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      include: {
        site: {
          select: {
            id: true,
            name: true
          }
        },
        mikroTikRouter: {
          select: {
            id: true,
            name: true,
            ipAddress: true,
          },
        },
        _count: {
          select: { hargaPaket: true },
        },
      },
    })

    return NextResponse.json(profilePPPs)
  } catch (error: unknown) {
    console.error('Error fetching profile PPPs:', error)
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Internal Server Error' },
      { status: 500 }
    )
  }
}

/**
 * @swagger
 * /api/profileppps:
 *   post:
 *     summary: Create new profile PPP
 *     description: Membuat profile PPP baru
 *     tags: [ProfilePPP]
 *     security:
 *       - bearerAuth: []
 *       - cookieAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - name
 *               - localAddress
 *               - remoteAddress
 *             properties:
 *               name:
 *                 type: string
 *                 example: "10Mbps-Profile"
 *                 description: Nama profile PPP
 *               localAddress:
 *                 type: string
 *                 example: "192.168.1.1"
 *                 description: Alamat local untuk PPP
 *               remoteAddress:
 *                 type: string
 *                 example: "192.168.1.100"
 *                 description: Alamat remote/nama pool untuk PPP
 *               dnsServer:
 *                 type: string
 *                 nullable: true
 *                 example: "8.8.8.8,8.8.4.4"
 *                 description: Server DNS
 *               sessionTimeout:
 *                 type: integer
 *                 nullable: true
 *                 example: 600
 *                 description: Timeout sesi dalam detik
 *               idleTimeout:
 *                 type: integer
 *                 nullable: true
 *                 example: 300
 *                 description: Timeout idle dalam detik
 *               ipRange:
 *                 type: string
 *                 nullable: true
 *                 example: "192.168.1.100-192.168.1.200"
 *                 description: "Range IP untuk pool (format: start-end)"
 *               mikroTikRouterId:
 *                 type: string
 *                 nullable: true
 *                 example: "clx1234567890"
 *                 description: ID MikroTik Router
 *               bandwidthId:
 *                 type: string
 *                 nullable: true
 *                 example: "clx1234567890"
 *                 description: ID Bandwidth untuk rate limit
 *               description:
 *                 type: string
 *                 nullable: true
 *                 example: "Profile untuk paket 10 Mbps"
 *                 description: Deskripsi profile
 *               status:
 *                 type: string
 *                 enum: ["AKTIF", "NONAKTIF"]
 *                 default: "AKTIF"
 *                 example: "AKTIF"
 *                 description: Status profile
 *     responses:
 *       201:
 *         description: Profile PPP berhasil dibuat
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/ProfilePPP'
 *       400:
 *         description: Validation error
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       401:
 *         description: Unauthorized
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       403:
 *         description: Forbidden
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       409:
 *         description: Nama profile PPP sudah digunakan
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       500:
 *         description: Server error
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 */
/**
 * POST /api/profileppps
 * Membuat Profile PPP baru
 * 
 * Alur:
 * 1. Validasi input (termasuk ipRange untuk IP Pool)
 * 2. Simpan Profile PPP ke database (tanpa ipRange, karena tidak disimpan)
 * 3. Jika ada mikroTikRouterId:
 *    - Buat IP Pool di MikroTik (jika ipRange disediakan)
 *    - Buat Profile PPP di MikroTik dengan remote-address = nama IP Pool
 */
export async function POST(req: NextRequest) {
  try {
    // Cek autentikasi admin menggunakan fungsi terpusat
    const session = await getServerSession(authOptions)
    if (!session || !session.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (!(await hasPermission("profileppp:create"))) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    }

    const body = await req.json()

    // Sanitize input dan convert empty strings to undefined/null
    const sanitizedBody = {
      name: body.name ? sanitizeInput(body.name) : undefined,
      localAddress: body.localAddress ? sanitizeInput(body.localAddress) : undefined,
      remoteAddress: body.remoteAddress ? sanitizeInput(body.remoteAddress) : undefined,
      // ipRange: Range IP untuk pool (contoh: "192.168.1.100-192.168.1.200")
      // Digunakan untuk membuat IP Pool di MikroTik, tidak disimpan di database
      ipRange: body.ipRange && body.ipRange.trim() ? sanitizeInput(body.ipRange) : undefined,
      dnsServer: body.dnsServer && body.dnsServer.trim() ? sanitizeInput(body.dnsServer) : undefined,
      sessionTimeout: body.sessionTimeout !== undefined && body.sessionTimeout !== null && body.sessionTimeout !== '' ? Number(body.sessionTimeout) : undefined,
      idleTimeout: body.idleTimeout !== undefined && body.idleTimeout !== null && body.idleTimeout !== '' ? Number(body.idleTimeout) : undefined,
      // Rate limit diambil dari Bandwidth yang terkait melalui HargaPaket atau bandwidthId langsung
      mikroTikRouterId: body.mikroTikRouterId && body.mikroTikRouterId.trim() ? body.mikroTikRouterId : undefined,
      bandwidthId: body.bandwidthId && body.bandwidthId.trim() ? body.bandwidthId : undefined, // Bandwidth untuk rate limit (opsional)
      description: body.description && body.description.trim() ? sanitizeInput(body.description) : undefined,
      status: body.status || 'AKTIF',
      siteId: body.siteId || undefined
    }

    // Enforce siteId for non-SUPER_ADMIN
    if (session.user.role !== "SUPER_ADMIN" && session.user.siteId) {
      sanitizedBody.siteId = session.user.siteId
    }

    // Log the creation attempt including siteId
    await import('@/lib/logger').then(({ logger }) => {
      logger.info('Creating Profile PPP', {
          userId: session.user.id,
          siteId: sanitizedBody.siteId,
          name: sanitizedBody.name
      })
    })

    // Validasi data dengan Zod schema
    const validation = profilePPPSchema.safeParse(sanitizedBody)
    if (!validation.success) {
      return NextResponse.json(
        { error: 'Validation error', details: validation.error.flatten() },
        { status: 400 }
      )
    }

    // Pisahkan ipRange dan bandwidthId dari data untuk Prisma
    // ipRange tidak disimpan di database, hanya digunakan untuk membuat IP Pool di MikroTik
    // bandwidthId tidak disimpan di database, hanya digunakan untuk mengambil rate limit
    const { ipRange: _ipRange, bandwidthId, ...rawPrismaData } = validation.data

    // Filter out undefined values to comply with exactOptionalPropertyTypes
    const prismaData: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(rawPrismaData)) {
      if (value !== undefined) {
        prismaData[key] = value
      }
    }

    // Simpan Profile PPP ke database
    const profilePPP = await prisma.profilePPP.create({
      data: {
        id: randomUUID(),
        ...prismaData,
        updatedAt: new Date(),
      } as any,
      include: {
        mikroTikRouter: true,
      },
    })

    // Jika ada mikroTikRouterId, buat profile PPP dan IP Pool di MikroTik Router
    // Alur: 1. Buat IP Pool (jika ipRange disediakan), 2. Buat Profile PPP dengan rate limit dari Bandwidth
    if (validation.data.mikroTikRouterId && profilePPP.mikroTikRouter) {
      try {
        console.log('[API ProfilePPP] Attempting to create profile in MikroTik router:', validation.data.mikroTikRouterId)

        // Ambil rate limit dari Bandwidth
        // Prioritas: 1. bandwidthId langsung (jika disediakan), 2. HargaPaket yang terkait
        const { getRateLimitFromBandwidth } = await import('@/modules/network/services/mikrotik-ppp-profile')
        const rateLimit = await getRateLimitFromBandwidth(profilePPP.id, bandwidthId)

        if (rateLimit) {
          console.log('[API ProfilePPP] Rate limit from bandwidth:', rateLimit)
        } else {
          console.log('[API ProfilePPP] No rate limit found from Bandwidth, creating profile without rate limit')
        }

        const mikrotikResult = await createPPPProfileInMikroTik(
          validation.data.mikroTikRouterId,
          {
            name: validation.data.name,
            localAddress: validation.data.localAddress,
            remoteAddress: validation.data.remoteAddress, // Nama IP Pool (sama dengan name)
            ...(validation.data.ipRange && { ipRange: validation.data.ipRange }),
            ...(validation.data.dnsServer && { dnsServer: validation.data.dnsServer }),
            ...(validation.data.sessionTimeout && { sessionTimeout: validation.data.sessionTimeout }),
            ...(validation.data.idleTimeout && { idleTimeout: validation.data.idleTimeout }),
            ...(rateLimit && { rateLimit }), // Rate limit dari Bandwidth (format: "10M/10M")
          }
        )

        if (!mikrotikResult.success) {
          console.error('[API ProfilePPP] Failed to create PPP profile in MikroTik:', mikrotikResult.error)
          // Jangan gagalkan request, hanya log error
          // Profile sudah dibuat di database, user bisa sync manual nanti jika diperlukan
        } else {
          console.log('[API ProfilePPP] Successfully created PPP profile in MikroTik')
        }
      } catch (mikrotikError: unknown) {
        console.error('[API ProfilePPP] Error creating PPP profile in MikroTik:', mikrotikError)
        if (mikrotikError instanceof Error) {
          console.error('[API ProfilePPP] Error stack:', mikrotikError.stack)
        }
        // Jangan gagalkan request, hanya log error
        // Profile sudah dibuat di database, user bisa sync manual nanti jika diperlukan
      }
    } else {
      // Jika tidak ada mikroTikRouterId yang dipilih, skip pembuatan profile di MikroTik
      console.log('[API ProfilePPP] No MikroTik router selected, skipping MikroTik profile creation')
    }

    return NextResponse.json(profilePPP, { status: 201 })
  } catch (error: unknown) {
    console.error('Error creating profile PPP:', error)

    // Handle unique constraint violation
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      if (error.code === 'P2002') {
        return NextResponse.json(
          { error: 'Nama profile PPP sudah digunakan' },
          { status: 400 }
        )
      }
    }

    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Internal Server Error' },
      { status: 500 }
    )
  }
}

import { NextResponse } from 'next/server'
import { getServerSession } from "next-auth"
import { authOptions } from "@/lib/auth"
import { hasPermission } from '@/lib/rbac'
import { getRoleService } from '@/modules/roles'
import { z } from 'zod'

const roleUpdateSchema = z.object({
    name: z.string().min(2),
    description: z.string().optional(),
    permissions: z.array(z.string()), // Array of permission IDs
    accessAdminPanel: z.boolean().optional(),
    accessEmployeePanel: z.boolean().optional(),
    isRestricted: z.boolean().optional(),
    isTechnical: z.boolean().optional()
})

// Fix for Next.js App Router params type
type Params = {
    params: Promise<{ id: string }>
}

export async function GET(req: Request, { params }: Params) {
    if (!await hasPermission('roles:read')) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    const { id } = await params

    try {
        const roleService = getRoleService()
        const role = await roleService.getRoleWithPermissions(id)

        if (!role) {
            return NextResponse.json({ error: 'Role not found' }, { status: 404 })
        }

        return NextResponse.json(role)
    } catch (error) {
        console.error('Error fetching role:', error)
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
    }
}

export async function PUT(req: Request, { params }: Params) {
    const session = await getServerSession(authOptions)
    if (!session) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (!await hasPermission('roles:update')) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    const { id } = await params

    try {
        const body = await req.json()
        const validated = roleUpdateSchema.parse(body)

        const roleService = getRoleService()
        const updateData: Record<string, unknown> = {
            name: validated.name,
            permissions: validated.permissions,
        }
        if (validated.description !== undefined) updateData.description = validated.description
        if (validated.accessAdminPanel !== undefined) updateData.accessAdminPanel = validated.accessAdminPanel
        if (validated.accessEmployeePanel !== undefined) updateData.accessEmployeePanel = validated.accessEmployeePanel
        if (validated.isRestricted !== undefined) updateData.isRestricted = validated.isRestricted
        if (validated.isTechnical !== undefined) updateData.isTechnical = validated.isTechnical

        const updatedRole = await roleService.updateRole(id, updateData as any)

        // Invalidate permission cache for all users with this role
        // This ensures the changes take effect immediately without re-login
        const { invalidateRolePermissionCache } = await import('@/lib/auth')
        await invalidateRolePermissionCache(id)

        // System Log
        try {
            const { logger } = await import('@/lib/logger')
            await logger.logActivity({
                action: 'UPDATE',
                subject: 'Role',
                userId: session.user.id ?? 'unknown',
                details: { id, updates: validated }
            })
        } catch (e: unknown) { console.error('Logging failed', e) }

        return NextResponse.json(updatedRole)
    } catch (error: unknown) {
        console.error('Error updating role:', error)
        if (error instanceof z.ZodError) {
            return NextResponse.json({ error: error.issues[0]?.message || 'Validation error' }, { status: 400 })
        }
        if (error instanceof Error) {
            if (error.message === 'Role not found') {
                return NextResponse.json({ error: error.message }, { status: 404 })
            }
            if (error.message === 'Cannot rename SUPER_ADMIN role') {
                return NextResponse.json({ error: error.message }, { status: 400 })
            }
            return NextResponse.json({ error: error.message }, { status: 400 })
        }
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
    }
}

export async function DELETE(req: Request, { params }: Params) {
    const session = await getServerSession(authOptions)
    if (!session) {
        // DELETE requires auth check for logging mainly, though permission check covers it
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (!await hasPermission('roles:delete')) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    const { id } = await params

    try {
        const roleService = getRoleService()
        await roleService.deleteRole(id)

        // System Log
        try {
            const { logger } = await import('@/lib/logger')
            await logger.logActivity({
                action: 'DELETE',
                subject: 'Role',
                userId: session.user.id ?? 'unknown',
                details: { id }
            })
        } catch (e: unknown) { console.error('Logging failed', e) }

        return NextResponse.json({ success: true })
    } catch (error: unknown) {
        console.error('Error deleting role:', error)
        if (error instanceof Error) {
            if (error.message === 'Role not found') {
                return NextResponse.json({ error: error.message }, { status: 404 })
            }
            if (error.message === 'Cannot delete SUPER_ADMIN role' ||
                error.message === 'Cannot delete role that has assigned users') {
                return NextResponse.json({ error: error.message }, { status: 400 })
            }
        }
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
    }
}

import { NextResponse } from 'next/server'
import { getServerSession } from "next-auth"
import { authConfig } from "@/lib/auth"
import { prisma } from '@/lib/prisma'
import { hasPermission } from '@/lib/rbac'
import { getRoleService } from '@/modules/roles'
import { z } from 'zod'

const roleSchema = z.object({
    name: z.string().min(2),
    description: z.string().optional(),
    permissions: z.array(z.string()), // Array of permission IDs
    accessAdminPanel: z.boolean().optional().default(false),
    accessEmployeePanel: z.boolean().optional().default(false),
    isRestricted: z.boolean().optional().default(false),
    isTechnical: z.boolean().optional().default(false)
})

export async function GET(req: Request) {
    // Allow access if user has roles:read OR users:create OR users:update permission
    // This enables users who manage users to see the role dropdown
    const canReadRoles = await hasPermission('roles:read')
    const canCreateUsers = await hasPermission('users:create')
    const canUpdateUsers = await hasPermission('users:update')

    if (!canReadRoles && !canCreateUsers && !canUpdateUsers) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    try {
        const { searchParams } = new URL(req.url)
        const filterRestricted = searchParams.get('filterRestricted') === 'true'

        const roleService = getRoleService()

        if (filterRestricted) {
            const session = await getServerSession(authConfig)

            if (session?.user?.id) {
                // Get current user's role info
                const currentUser = await prisma.user.findUnique({
                    where: { id: session.user.id },
                    select: { roleId: true, role: { select: { name: true } } }
                })

                console.log('[Roles API] Current user role:', currentUser?.role?.name)

                const roles = await roleService.getAllRoles({
                    filterRestricted: true,
                    currentUserRoleId: currentUser?.roleId ?? null,
                    currentUserRoleName: currentUser?.role?.name ?? null
                })

                return NextResponse.json(roles)
            } else {
                // No session - show only non-restricted roles
                const roles = await roleService.getAllRoles({
                    filterRestricted: true,
                    currentUserRoleName: null
                })
                return NextResponse.json(roles)
            }
        }

        // No filter - return all roles
        const roles = await roleService.getAllRoles()
        return NextResponse.json(roles)
    } catch (error) {
        console.error('Error fetching roles:', error)
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
    }
}

export async function POST(req: Request) {
    if (!await hasPermission('roles:create')) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    try {
        const body = await req.json()
        const validated = roleSchema.parse(body)

        const roleService = getRoleService()

        // Build the role data conditionally to avoid passing undefined
        const roleData: Record<string, unknown> = {
            name: validated.name,
            permissions: validated.permissions,
        }

        // Only include optional properties if they have values
        if (validated.description !== undefined) roleData.description = validated.description
        if (validated.accessAdminPanel !== undefined) roleData.accessAdminPanel = validated.accessAdminPanel
        if (validated.accessEmployeePanel !== undefined) roleData.accessEmployeePanel = validated.accessEmployeePanel
        if (validated.isRestricted !== undefined) roleData.isRestricted = validated.isRestricted
        if (validated.isTechnical !== undefined) roleData.isTechnical = validated.isTechnical

        const newRole = await roleService.createRole(roleData as any)

        // System Log
        try {
            const session = await getServerSession(authConfig)
            if (session?.user?.id) {
                const { logger } = await import('@/lib/logger')
                await logger.logActivity({
                    action: 'CREATE',
                    subject: 'Role',
                    userId: session.user.id,
                    details: { id: newRole.id, name: newRole.name }
                })
            }
        } catch (e) {
            console.error('Logging failed', e)
        }

        return NextResponse.json(newRole)
    } catch (error) {
        console.error('Error creating role:', error)
        if (error instanceof z.ZodError) {
            return NextResponse.json({ error: error.issues[0]?.message || 'Validation error' }, { status: 400 })
        }
        if (error instanceof Error) {
            return NextResponse.json({ error: error.message }, { status: 400 })
        }
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 })
    }
}

import { NextResponse } from "next/server";
import { getHybridUser } from "@/lib/hybrid-auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: Request) {
  const user = await getHybridUser(req) as any;

  if (!user) {
    return new NextResponse("Unauthorized", { status: 401 });
  }

  try {
    const where: { id?: string } = {};

    // Check for site restriction: NOT Super Admin AND has siteId assigned
    if (user.role !== 'SUPER_ADMIN' && user.siteId) {
        where.id = user.siteId;
    }

    const sites = await prisma.sites.findMany({
      where,
      orderBy: {
        name: "asc",
      },
      select: {
        id: true,
        name: true,
      },
    });

    return NextResponse.json({ sites });
  } catch (error) {
    console.error("[SITES_GET]", error);
    return new NextResponse("Internal Error", { status: 500 });
  }
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authConfig } from '@/lib/auth'
import { getSpeedProfileRepository } from '@/lib/repositories'
import { speedProfileCreateSchema } from '@/lib/validations/speedprofile'

async function requireAdmin() {
  const session = await getServerSession(authConfig)
  if (!session) {
    return null
  }
  return session
}

export async function GET() {
  try {
    const session = await requireAdmin()
    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    try {
      const speedProfileRepository = getSpeedProfileRepository()
      const speedProfiles = await speedProfileRepository.findAll()
      return NextResponse.json({ speedProfiles })
    } catch (repoError: unknown) {
      console.error('Error in SpeedProfileRepository:', repoError)
      // Jika error terkait model tidak ditemukan
      if (repoError instanceof Error && (repoError.message?.includes('findMany') || repoError.message?.includes('speedProfile') || (repoError as any).code === 'P2021')) {
        return NextResponse.json(
          {
            error: 'Model SpeedProfile belum tersedia. Silakan restart server Next.js setelah menjalankan: npx prisma generate',
            speedProfiles: []
          },
          { status: 500 }
        )
      }
      throw repoError
    }
  } catch (error: unknown) {
    console.error('Error fetching SpeedProfiles:', error)
    // Jika error terkait tabel tidak ditemukan, beri pesan yang lebih jelas
    if (error instanceof Error && ((error as any).code === 'P2021' || error.message?.includes('does not exist') || error.message?.includes('Unknown model'))) {
      return NextResponse.json(
        {
          error: 'Tabel SpeedProfile belum dibuat di database. Silakan jalankan: npx prisma db push --accept-data-loss',
          speedProfiles: []
        },
        { status: 500 }
      )
    }
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Gagal memuat data SpeedProfile', speedProfiles: [] },
      { status: 500 }
    )
  }
}

export async function POST(req: Request) {
  const session = await requireAdmin()
  if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const json = await req.json()
  const parsed = speedProfileCreateSchema.safeParse(json)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }
  const data = parsed.data
  try {
    const speedProfileRepository = getSpeedProfileRepository()
    const speedProfile = await speedProfileRepository.create({
      oltId: data.oltId,
      profileType: data.profileType,
      name: data.name,
      type: data.type,
      bandwidthSir: data.bandwidthSir,
      burstPir: data.burstPir,
      fixed: data.fixed ?? null,
      assured: data.assured ?? null,
      maximum: data.maximum ?? null,
    })
    // System Log
    try {
      const { logger } = await import('@/lib/logger')
      await logger.logActivity({
        action: 'CREATE',
        subject: 'SpeedProfile',
        userId: session.user.id,
        details: { id: speedProfile.id, name: data.name }
      })
    } catch (e) {
      console.error('Logging failed', e)
    }

    return NextResponse.json({ id: speedProfile.id })
  } catch (_e) {
    return NextResponse.json({ error: 'SpeedProfile dengan nama tersebut sudah ada untuk OLT ini atau terjadi kesalahan' }, { status: 409 })
  }
}

"use client"

import React, { useRef, useEffect, useState } from 'react'
import type Map from 'ol/Map'
import type VectorLayer from 'ol/layer/Vector'
import type VectorSource from 'ol/source/Vector'

// Komponen peta berbasis OpenLayers. Pastikan memasang dependency: npm i ol
// Minimal init: tile OSM, click untuk set koordinat, serta marker sederhana.

type MapPickerProps = {
  lat?: number | null
  lon?: number | null
  height?: number | undefined
  onChange: (lat: number, lon: number) => void
}

export default function MapPicker({ lat, lon, height = 360, onChange }: MapPickerProps) {
  const mapEl = useRef<HTMLDivElement | null>(null)
  const mapRef = useRef<Map | null>(null)
  const markerLayerRef = useRef<VectorLayer<VectorSource> | null>(null)
  const onChangeRef = useRef(onChange)

  // Keep onChange ref updated
  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  useEffect(() => {
    let cleanup = () => { }
    let isMounted = true
      ; (async () => {
        const { Map, View } = await import('ol')
        const { default: OSM } = await import('ol/source/OSM')
        const { default: TileLayer } = await import('ol/layer/Tile')
        const { default: VectorLayer } = await import('ol/layer/Vector')
        const { default: VectorSource } = await import('ol/source/Vector')
        const { fromLonLat, toLonLat } = await import('ol/proj')
        const { default: Feature } = await import('ol/Feature')
        const { default: Point } = await import('ol/geom/Point')
        const { Style, Fill, Stroke } = await import('ol/style')
        const { default: CircleStyle } = await import('ol/style/Circle')
        const { defaults: defaultControls, Zoom, Attribution } = await import('ol/control')

        if (!isMounted || !mapEl.current) return

        const centerLonLat: [number, number] = [
          typeof lon === 'number' ? lon : 106.816666,
          typeof lat === 'number' ? lat : -6.2,
        ]
        const center3857 = fromLonLat(centerLonLat)

        const tile = new TileLayer({ source: new OSM() })
        const markerSource = new VectorSource()
        const marker = new VectorLayer({ source: markerSource })
        markerLayerRef.current = marker

        const map = new Map({
          target: mapEl.current as HTMLDivElement,
          layers: [tile, marker],
          view: new View({ center: center3857, zoom: 14 }),
          controls: defaultControls({ zoom: false, rotate: false, attribution: false }).extend([
            new Zoom(),
            new Attribution({ collapsible: true, collapsed: true }),
          ]),
        })
        mapRef.current = map

        if (typeof lat === 'number' && typeof lon === 'number') {
          const f = new Feature({ geometry: new Point(fromLonLat([lon, lat])) })
          f.setStyle(new Style({ image: new CircleStyle({ radius: 6, fill: new Fill({ color: '#2563eb' }), stroke: new Stroke({ color: '#ffffff', width: 2 }) }) }))
          markerSource.clear(); markerSource.addFeature(f)
        }

        const clickHandler = (evt: { coordinate: [number, number] }) => {
          if (!isMounted) return
          const coord3857 = evt.coordinate
          const [lonC, latC] = toLonLat(coord3857)
          if (typeof latC !== 'number' || typeof lonC !== 'number') return
          const f = new Feature({ geometry: new Point(coord3857) })
          f.setStyle(new Style({ image: new CircleStyle({ radius: 6, fill: new Fill({ color: '#2563eb' }), stroke: new Stroke({ color: '#ffffff', width: 2 }) }) }))
          markerSource.clear(); markerSource.addFeature(f)
          try {
            const view = map.getView();
            view.animate({ center: coord3857, zoom: Math.max(17, view.getZoom() || 0), duration: 400 })
          } catch { }
          onChangeRef.current(Number(latC.toFixed(6)), Number(lonC.toFixed(6)))
        }

        map.on('click', clickHandler as never)
        const externalSetHandler = (e: CustomEvent<{ lat?: number; lon?: number }>) => {
          if (!isMounted) return
          try {
            const { lat: la, lon: lo } = e.detail || {}
            if (typeof la === 'number' && typeof lo === 'number') {
              const f = new Feature({ geometry: new Point(fromLonLat([lo, la])) })
              f.setStyle(new Style({ image: new CircleStyle({ radius: 6, fill: new Fill({ color: '#2563eb' }), stroke: new Stroke({ color: '#ffffff', width: 2 }) }) }))
              markerSource.clear(); markerSource.addFeature(f)
              const view = map.getView()
              const center = fromLonLat([lo, la])
              view.animate({ center, zoom: Math.max(17, view.getZoom() || 0), duration: 400 })
            }
          } catch { }
        }
        window.addEventListener('mappicker-set', externalSetHandler as EventListener)

        cleanup = () => {
          isMounted = false
          try {
            window.removeEventListener('mappicker-set', externalSetHandler as EventListener)
            if (mapRef.current) {
              mapRef.current.un('click', clickHandler as never)
              mapRef.current.setTarget(undefined)
              mapRef.current.dispose()
              mapRef.current = null
            }
          } catch (_e) {
            // Ignore cleanup errors
          }
        }
      })()

    return () => {
      isMounted = false
      cleanup()
    }
  }, [lat, lon])

  // Update marker jika lat/lon berubah dari luar (misal hasil geolocate)
  useEffect(() => {
    ; (async () => {
      if (!markerLayerRef.current || !mapRef.current) return
      const { default: Feature } = await import('ol/Feature')
      const { default: Point } = await import('ol/geom/Point')
      const { fromLonLat } = await import('ol/proj')
      const { Style, Fill, Stroke } = await import('ol/style')
      const { default: CircleStyle } = await import('ol/style/Circle')
      const source = markerLayerRef.current.getSource()
      if (!source) return
      if (typeof lat === 'number' && typeof lon === 'number') {
        const f = new Feature({ geometry: new Point(fromLonLat([lon, lat])) })
        f.setStyle(new Style({ image: new CircleStyle({ radius: 6, fill: new Fill({ color: '#2563eb' }), stroke: new Stroke({ color: '#ffffff', width: 2 }) }) }))
        source.clear(); source.addFeature(f)
        try {
          const view = mapRef.current.getView()
          const center = fromLonLat([lon, lat])
          view.animate({ center, zoom: Math.max(17, view.getZoom() || 0), duration: 400 })
        } catch { }
      }
    })()
  }, [lat, lon])

  return <div ref={mapEl} style={{ height, width: '100%', borderRadius: 8, overflow: 'hidden' }} />
}

export function MapPickerWithSearch(props: MapPickerProps) {
  const [lat, setLat] = useState<number | null>(props.lat ?? null)
  const [lon, setLon] = useState<number | null>(props.lon ?? null)
  const [query, setQuery] = useState('')
  const [searching, setSearching] = useState(false)
  const [results, setResults] = useState<Array<{ displayName: string; lat: number; lon: number }>>([])

  async function handleSearch() {
    setSearching(true)
    try {
      const res = await fetch(`/api/geocode/search?q=${encodeURIComponent(query)}`)
      const j: { results: Array<{ displayName: string; lat: number; lon: number }> } = await res.json().catch(() => ({ results: [] as any[] }))
      setResults(j.results || [])
    } finally {
      setSearching(false)
    }
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Cari alamat atau tempat" className="flex-1 rounded-md border border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-900 px-3 py-2 text-sm" />
        <button type="button" onClick={handleSearch} className="rounded-md border border-gray-300 dark:border-gray-700 px-3 py-2 text-sm">{searching ? 'Mencari…' : 'Cari'}</button>
      </div>
      {results.length > 0 && (
        <div className="max-h-40 overflow-auto rounded-md border border-gray-200 dark:border-gray-800">
          {results.map((r, i) => (
            <button key={i} type="button" onClick={() => { setLat(r.lat); setLon(r.lon); setResults([]); try { window.dispatchEvent(new CustomEvent('mappicker-set', { detail: { lat: r.lat, lon: r.lon } })) } catch (_e) { }; props.onChange(r.lat, r.lon) }} className="block w-full text-left px-3 py-2 text-sm hover:bg-gray-50 dark:hover:bg-gray-800">
              {r.displayName}
            </button>
          ))}
        </div>
      )}
      <MapPicker lat={lat} lon={lon} height={props.height} onChange={(la, lo) => { setLat(la); setLon(lo); props.onChange(la, lo) }} />
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  FiCheckCircle,
  FiAlertTriangle,
  FiXCircle
} from 'react-icons/fi'
import { PhotoUpload } from './PhotoUpload'
import type { PhotoUploadRef, UploadedPhoto } from './PhotoUpload'
import { getWithAuth, postWithAuth } from '@/lib/api-client'

interface Barang {
  id: string
  kode: string
  nama: string
  satuan: string
  stockPerGudang?: Array<{
    gudangId: string
    stok: number
  }>
}

interface Gudang {
  id: string
  kode: string
  nama: string
  lokasi?: string
}

interface Photo {
  id: string
  url?: string
  status: 'pending' | 'uploading' | 'success' | 'error'
  file?: File
  error?: string
}

interface TransferFormProps {
  initialData?: unknown
  onClose: () => void
  onSuccess?: () => void
}

export function TransferForm({ initialData: _initialData, onClose, onSuccess }: TransferFormProps) {
  const [formData, setFormData] = useState({
    barangId: '',
    dariGudangId: '',
    keGudangId: '',
    jumlah: '',
    kondisi: 'BARU' as 'BARU' | 'BEKAS' | 'RUSAK',
    keterangan: ''
  })
  const [barangs, setBarangs] = useState<Barang[]>([])
  const [gudangs, setGudangs] = useState<Gudang[]>([])
  const [stockSumber, setStockSumber] = useState(0)
  const [stockPerKondisi, setStockPerKondisi] = useState({
    BARU: 0,
    BEKAS: 0,
    RUSAK: 0
  })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')
  const [_uploadedPhotos, setUploadedPhotos] = useState<UploadedPhoto[]>([])
  const [transactionId, _setTransactionId] = useState<string | null>(null)
  const photoUploadRef = useRef<PhotoUploadRef>(null)
  const router = useRouter()

  useEffect(() => {
    async function fetchInitialData() {
      try {
        // Fetch barang
        const barangResponse = await getWithAuth('/api/inventory/barang?limit=100')
        const barangData = await barangResponse.json()
        const barangResult = barangData.data || barangData
        setBarangs(barangResult.barangs || [])

        // Fetch gudang
        const gudangResponse = await getWithAuth('/api/inventory/gudang')
        const gudangData = await gudangResponse.json()
        const gudangResult = gudangData.data || gudangData
        setGudangs(gudangResult.gudangs || [])
      } catch (error) {
        console.error('Error fetching initial data:', error)
        setError('Gagal memuat data awal')
      }
    }

    fetchInitialData()
  }, [])

  useEffect(() => {
    async function fetchStockByCondition() {
      if (formData.barangId && formData.dariGudangId) {
        try {
          // Fetch condition-specific stock from API
          const response = await getWithAuth(
            `/api/inventory/barang/stock/by-kondisi?barangId=${formData.barangId}&gudangId=${formData.dariGudangId}`
          )
          if (response.ok) {
            const data = await response.json()
            const result = data.data || data
            setStockPerKondisi(result.stockPerKondisi || { BARU: 0, BEKAS: 0, RUSAK: 0 })
            setStockSumber(result.totalStock || 0)
          } else {
            // Fallback to current logic if API fails
            const selectedBarang = barangs.find(b => b.id === formData.barangId)
            if (selectedBarang) {
              const stockInfo = selectedBarang.stockPerGudang?.find((s: { gudangId: string, stok: number }) => s.gudangId === formData.dariGudangId)
              setStockSumber(stockInfo?.stok || 0)
            }
          }
        } catch (error) {
          console.error('Error fetching stock by condition:', error)
          // Fallback to current logic
          const selectedBarang = barangs.find(b => b.id === formData.barangId)
          if (selectedBarang) {
            const stockInfo = selectedBarang.stockPerGudang?.find((s: { gudangId: string, stok: number }) => s.gudangId === formData.dariGudangId)
            setStockSumber(stockInfo?.stok || 0)
          }
        }
      } else {
        setStockPerKondisi({ BARU: 0, BEKAS: 0, RUSAK: 0 })
        setStockSumber(0)
      }
    }

    fetchStockByCondition()
  }, [formData.barangId, formData.dariGudangId, barangs])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    // Validation
    if (!formData.barangId || !formData.dariGudangId || !formData.keGudangId || !formData.jumlah) {
      setError('Barang, gudang sumber, gudang tujuan, dan jumlah harus diisi')
      return
    }

    if (formData.dariGudangId === formData.keGudangId) {
      setError('Gudang sumber dan tujuan tidak boleh sama')
      return
    }

    const jumlah = parseInt(formData.jumlah)
    if (isNaN(jumlah) || jumlah <= 0) {
      setError('Jumlah harus berupa angka positif')
      return
    }

    const availableStockForCondition = stockPerKondisi[formData.kondisi] || 0
    if (jumlah > availableStockForCondition) {
      setError(`Jumlah ${formData.kondisi.toLowerCase()} tidak boleh melebihi stok tersedia (${availableStockForCondition})`)
      return
    }

    setLoading(true)
    setError('')
    setSuccess('')

    try {
      // Upload photos first if any exist
      let fotoBuktiUrls: string[] = []
      let uploadedPhotosList: UploadedPhoto[] = []

      if (photoUploadRef.current) {
        const currentPhotos = photoUploadRef.current.getPhotos()

        if (currentPhotos.length > 0) {
          setSuccess('Mengunggah foto...')

          // Upload photos
          fotoBuktiUrls = await photoUploadRef.current.uploadPhotos()

          // Get updated photos after upload
          uploadedPhotosList = photoUploadRef.current.getPhotos()

          // Check if any photos failed to upload
          const failedPhotos = uploadedPhotosList.filter(photo => photo.status === 'error')
          if (failedPhotos.length > 0) {
            throw new Error(`Beberapa foto gagal diunggah: ${failedPhotos.map(p => p.error).join(', ')}`)
          }
        }
      }

      const response = await postWithAuth('/api/inventory/transfer', {
        ...formData,
        jumlah,
        fotoBukti: fotoBuktiUrls,
        fotoMetadata: uploadedPhotosList.length > 0 ? {
          uploadedAt: new Date().toISOString(),
          count: uploadedPhotosList.length,
          totalSize: uploadedPhotosList.reduce((sum, photo) => sum + (photo.file?.size || 0), 0)
        } : null
      })

      const data = await response.json()

      if (!data.success) {
        // Cleanup uploaded photos if transfer failed
        if (fotoBuktiUrls.length > 0) {
          try {
            await Promise.allSettled(
              fotoBuktiUrls.map(url =>
                fetch(url.replace('/uploads/', '/api/uploads/delete/'), {
                  method: 'DELETE'
                }).catch(err => console.error('Failed to cleanup photo:', err))
              )
            )
          } catch (cleanupError) {
            console.error('Error during photo cleanup:', cleanupError)
          }
        }
        throw new Error(data.error || 'Gagal melakukan transfer')
      }

      const result = data.data || data
      setSuccess(`Transfer berhasil! Kode transfer: ${result.kodeTransfer}`)

      // Reset form
      setFormData({
        barangId: '',
        dariGudangId: '',
        keGudangId: '',
        jumlah: '',
        kondisi: 'BARU',
        keterangan: ''
      })
      setStockSumber(0)
      setStockPerKondisi({ BARU: 0, BEKAS: 0, RUSAK: 0 })
      setUploadedPhotos([])
      // Reset photo upload component
      if (photoUploadRef.current) {
        photoUploadRef.current.resetPhotos()
      }

      // Close form after 2 seconds
      setTimeout(() => {
        onClose()
        if (onSuccess) {
          onSuccess()
        }
        // Refresh the page to show updated data
        router.refresh()
      }, 2000)

    } catch (error) {
      console.error('Error submitting transfer:', error)
      setError(error instanceof Error ? error.message : 'Terjadi kesalahan')
    } finally {
      setLoading(false)
    }
  }

  const selectedBarang = barangs.find(b => b.id === formData.barangId)
  const selectedGudangSumber = gudangs.find(g => g.id === formData.dariGudangId)
  const selectedGudangTujuan = gudangs.find(g => g.id === formData.keGudangId)

  const getStockStatusColor = (stock: number) => {
    if (stock === 0) return 'text-red-600 font-bold'
    if (stock < 5) return 'text-yellow-600 font-semibold'
    return 'text-green-600'
  }

  const getKondisiColor = (kondisi: string) => {
    switch (kondisi) {
      case 'BARU': return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300'
      case 'BEKAS': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300'
      case 'RUSAK': return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300'
      default: return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-300'
    }
  }

  // Filter gudang tujuan to exclude gudang sumber
  const availableGudangTujuan = gudangs.filter(g => g.id !== formData.dariGudangId)

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {error && (
        <div className="p-4 bg-red-50 border border-red-200 rounded-md text-red-800">
          {error}
        </div>
      )}

      {success && (
        <div className="p-4 bg-green-50 border border-green-200 rounded-md text-green-800">
          {success}
        </div>
      )}

      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
        <div>
          <label htmlFor="dariGudangId" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            Gudang Sumber *
          </label>
          <select
            id="dariGudangId"
            value={formData.dariGudangId}
            onChange={(e) => setFormData({ ...formData, dariGudangId: e.target.value })}
            className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            disabled={loading}
          >
            <option value="">Pilih gudang sumber</option>
            {gudangs.map((gudang) => (
              <option key={gudang.id} value={gudang.id}>
                {gudang.kode} - {gudang.nama}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="keGudangId" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            Gudang Tujuan *
          </label>
          <select
            id="keGudangId"
            value={formData.keGudangId}
            onChange={(e) => setFormData({ ...formData, keGudangId: e.target.value })}
            className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            disabled={loading || !formData.dariGudangId}
          >
            <option value="">Pilih gudang tujuan</option>
            {availableGudangTujuan.map((gudang) => (
              <option key={gudang.id} value={gudang.id}>
                {gudang.kode} - {gudang.nama}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
        <div>
          <label htmlFor="barangId" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            Barang *
          </label>
          <select
            id="barangId"
            value={formData.barangId}
            onChange={(e) => setFormData({ ...formData, barangId: e.target.value })}
            className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            disabled={loading}
          >
            <option value="">Pilih barang</option>
            {barangs.map((barang) => (
              <option key={barang.id} value={barang.id}>
                {barang.kode} - {barang.nama}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="kondisi" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            Kondisi Barang *
          </label>
          <select
            id="kondisi"
            value={formData.kondisi}
            onChange={(e) => setFormData({ ...formData, kondisi: e.target.value as 'BARU' | 'BEKAS' | 'RUSAK' })}
            className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            disabled={loading}
          >
            <option value="BARU" disabled={stockPerKondisi.BARU === 0}>
              Baru {stockPerKondisi.BARU > 0 ? `(${stockPerKondisi.BARU})` : '(Tidak tersedia)'}
            </option>
            <option value="BEKAS" disabled={stockPerKondisi.BEKAS === 0}>
              Bekas {stockPerKondisi.BEKAS > 0 ? `(${stockPerKondisi.BEKAS})` : '(Tidak tersedia)'}
            </option>
            <option value="RUSAK" disabled={stockPerKondisi.RUSAK === 0}>
              Rusak {stockPerKondisi.RUSAK > 0 ? `(${stockPerKondisi.RUSAK})` : '(Tidak tersedia)'}
            </option>
