import { AssetRepository } from '../repositories/AssetRepository'
import type { CreateAssetInput, UpdateAssetInput, AssetWithRelations } from '../repositories/AssetRepository'
import { FinanceService } from '../../finance/services/FinanceService'
import { AssetStatus } from '@prisma/client'
import { logger } from '@/lib/logger'

export class AssetService {
    private assetRepo: AssetRepository
    private financeService: FinanceService

    constructor() {
        this.assetRepo = new AssetRepository()
        this.financeService = new FinanceService()
    }

    async createAsset(data: CreateAssetInput, userId: string) {
        // Create the asset
        const asset = await this.assetRepo.createAsset(data)

        // Log Activity
        try {
            await logger.logActivity({
                action: 'CREATE',
                subject: 'Asset',
                userId: userId,
                details: {
                    id: asset.id,
                    kodeAsset: asset.kodeAsset,
                    barangId: asset.barangId,
                    purchasePrice: asset.purchasePrice,
                    status: asset.status
                }
            })
        } catch (error) {
            console.error('Failed to log asset creation:', error)
        }

        // Note: Initial Purchase expense is usually handled via Purchase Order / Finance separately
        // so we don't auto-create transaction here unless explicitly requested.
        // But we DO expect this asset to be capitalized.

        return asset
    }

    async getAsset(id: string): Promise<AssetWithRelations | null> {
        return this.assetRepo.findAssetById(id)
    }

    async updateAsset(id: string, data: UpdateAssetInput, userId?: string) {
        const result = await this.assetRepo.updateAsset(id, data)

        // Log Activity
        if (userId) {
            try {
                await logger.logActivity({
                    action: 'UPDATE',
                    subject: 'Asset',
                    userId: userId,
                    details: {
                        id: result.id,
                        kodeAsset: result.kodeAsset,
                        updates: data
                    }
                })
            } catch (error) {
                console.error('Failed to log asset update:', error)
            }
        }

        return result
    }

    async findAllAssets(params: {
        page?: number
        limit?: number
        search?: string
        status?: AssetStatus
        barangId?: string
        location?: string
    }) {
        const { page = 1, limit = 10, ...rest } = params
        const skip = (page - 1) * limit
        return this.assetRepo.findAllAssets({
            skip,
            take: limit,
            ...rest
        })
    }

    /**
     * Calculates and processes monthly depreciation for a single asset.
     * Use this for ad-hoc or scheduled runs per asset.
     */
    async depreciateAsset(assetId: string, customDate: Date = new Date(), createdById: string) {
        const asset = await this.assetRepo.findAssetById(assetId)
        if (!asset) throw new Error('Asset not found')

        if (asset.status !== 'ACTIVE' && asset.status !== 'INSTALLED') {
            throw new Error(`Asset status is ${asset.status}, cannot depreciate.`)
        }

        if (asset.currentValue.toNumber() <= asset.residualValue.toNumber()) {
            return null // No depreciation needed, already at residual value
        }

        // Calculation: Straight Line
        // (Cost - Residual) / UsefulLife
        const cost = asset.purchasePrice.toNumber()
        const residual = asset.residualValue.toNumber()
        const lifeMonths = asset.usefulLife

        if (lifeMonths <= 0) throw new Error('Useful life must be > 0')

        const monthlyAmount = (cost - residual) / lifeMonths

        // Check if remaining value < monthlyAmount
        let actualAmount = monthlyAmount
        const currentVal = asset.currentValue.toNumber()

        // Ensure we don't go below residual
        if (currentVal - monthlyAmount < residual) {
            actualAmount = currentVal - residual
        }

        if (actualAmount <= 0) return null

        // 1. Record in Asset Log & Update Asset Value
        const log = await this.assetRepo.recordDepreciation(
            asset.id,
            actualAmount,
            `Depreciation for ${customDate.toLocaleString('default', { month: 'long', year: 'numeric' })}`
        )

        // 2. Create Finance Expense
        // Find or create "Depreciation" category
        // For now, we search for a category named "Depreciation" or "Penyusutan" or "Beban Penyusutan"
        // TODO: Refactor to have a System Config for default categories
        const categories = await this.financeService.getAllCategories()
        let depCategory = categories.find(c => 
            c.name.toLowerCase().includes('penyusutan') || 
            c.name.toLowerCase().includes('depreciation')
        )

        if (!depCategory) {
            // Recommendation: Do not auto-create "Beban Penyusutan" to prevent polluting Chart of Accounts.
            // Throw an explicit error asking the admin to configure it.
            throw new Error('Finance Category for Depreciation (e.g. "Beban Penyusutan") not found. Please create it in Finance Settings.')
        }

        await this.financeService.createTransaction({
            type: 'EXPENSE',
            amount: actualAmount,
            date: customDate,
            categoryId: depCategory.id,
            description: `Penyusutan Aset: ${asset.barang.nama} (${asset.kodeAsset})`,
            createdById: createdById,
            referenceId: log.id // Link to log
        })

        // Log Activity
        try {
            await logger.logActivity({
                action: 'DEPRECIATE',
                subject: 'Asset',
                userId: createdById,
                details: {
                    id: asset.id,
                    kodeAsset: asset.kodeAsset,
                    amount: actualAmount,
                    period: customDate.toISOString()
                }
            })
        } catch (error) {
            console.error('Failed to log asset depreciation:', error)
        }

        return log
    }

    /**
     * Run monthly depreciation for ALL active assets.
     * To be called by Cron Job.
     */
    async runMonthlyDepreciationCycle(createdById: string) {
        const assets = await this.assetRepo.getActiveAssetsForDepreciation()
        const results = []

        for (const asset of assets) {
            try {
                const res = await this.depreciateAsset(asset.id, new Date(), createdById)
                if (res) results.push(res)
            } catch (error) {
                console.error(`Failed to depreciate asset ${asset.kodeAsset}:`, error)
                // Continue to next asset
            }
        }
        return results
    }
}

import { PrismaClient, Prisma } from '@prisma/client'
import { randomUUID } from 'crypto'
import { prisma } from '@/lib/prisma'
import { onuCacheService } from '../services/onu-cache-service'
import type {
  IOnuRepository,
  OnuCreateData,
  OnuUpdateData,
  OnuPublic,
  OnuFilters,
  PaginationOptions,
  PaginatedOnuResult,
  OnuSummaryStats
} from './IOnuRepository'

export class OnuRepository implements IOnuRepository {
  constructor(private client: PrismaClient = prisma) { }

  async findAll(): Promise<OnuPublic[]> {
    // Gunakan sorting yang stabil berdasarkan gponOnu dan oltId untuk konsistensi
    // Jangan gunakan lastUpdate karena bisa berubah setiap kali ada sync
    const onus = await this.client.onu.findMany({
      orderBy: [
        { oltId: 'asc' },
        { gponOnu: 'asc' }
      ],
      include: {
        olt: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    })
    return onus as OnuPublic[]
  }

  async findWithFilters(filters: OnuFilters, pagination: PaginationOptions): Promise<PaginatedOnuResult> {
    const { page, limit } = pagination
    const skip = (page - 1) * limit

    // Build where clause dynamically
    const whereConditions: Prisma.OnuWhereInput[] = []

    // Filter by OLT ID (prioritas lebih tinggi dari oltName)
    if (filters.oltId) {
      whereConditions.push({ oltId: filters.oltId })
    } else if (filters.oltName) {
      // Get OLT by name
      const olt = await this.client.olt.findFirst({
        where: { name: filters.oltName },
        select: { id: true },
      })
      if (olt) {
        whereConditions.push({ oltId: olt.id })
      } else {
        // If OLT not found, return empty result
        return {
          onus: [],
          total: 0,
          page,
          limit,
          totalPages: 0,
        }
      }
    }

    // Filter by Card (Frame) - parse gponOnu format: Frame/Slot/Port:OnuID
    if (filters.card) {
      whereConditions.push({
        gponOnu: {
          startsWith: `${filters.card}/`,
        },
      })
    }

    // Filter by Port (PON) - parse gponOnu format: Frame/Slot/Port:OnuID
    if (filters.port) {
      // We need to check the third segment (Port)
      // This is a bit tricky with Prisma, we'll need to get all and filter
      // For now, we use contains which is not perfect but works
      whereConditions.push({
        gponOnu: {
          contains: `/${filters.port}:`,
        },
      })
    }

    // Filter by ONU Type
    if (filters.type) {
      whereConditions.push({ actualType: filters.type })
    }

    // Filter by Status
    if (filters.status) {
      let statusValue = filters.status
      if (filters.status === 'online') {
        statusValue = 'Online'
      } else if (filters.status === 'dyinggasp') {
        statusValue = 'DyingGasp'
      } else if (filters.status === 'los') {
        statusValue = 'LOS'
      }
      whereConditions.push({ status: statusValue })
    }

    // Search across multiple fields
    if (filters.search) {
      whereConditions.push({
        OR: [
          { name: { contains: filters.search, mode: 'insensitive' } },
          { description: { contains: filters.search, mode: 'insensitive' } },
          { pppoe: { contains: filters.search, mode: 'insensitive' } },
          { gponOnu: { contains: filters.search, mode: 'insensitive' } },
          { serialNumber: { contains: filters.search, mode: 'insensitive' } },
        ],
      })
    }

    // Combine all where conditions
    const whereClause: Prisma.OnuWhereInput = whereConditions.length > 0
      ? { AND: whereConditions }
      : {}

    // Debug logging untuk troubleshooting
    if (filters.oltId) {
      console.log(`[OnuRepository] findWithFilters: oltId=${filters.oltId}, whereClause:`, JSON.stringify(whereClause))
    }

    // Get all ONUs for signal filtering (if needed)
    let allOnus: OnuPublic[] = []
    if (filters.signal) {
      // We need to fetch all matching ONUs to filter by signal
      allOnus = await this.client.onu.findMany({
        where: whereClause,
        orderBy: { lastUpdate: 'desc' },
        include: {
          olt: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      }) as OnuPublic[]

      // Filter by signal quality
      allOnus = allOnus.filter((onu) => {
        const rxOlt = onu.rxOlt ? parseFloat(onu.rxOlt.replace(/[^\d.-]/g, '')) : null

        if (filters.signal === 'good' && rxOlt !== null && rxOlt >= -26.0) return true
        if (filters.signal === 'warning' && rxOlt !== null && rxOlt >= -28.0 && rxOlt < -26.0) return true
        if (filters.signal === 'critical' && rxOlt !== null && rxOlt < -28.0) return true
        if (filters.signal === 'other' && (rxOlt === null || onu.status === 'LOS' || onu.status === 'DyingGasp')) return true

        return false
      })

      // Apply pagination to filtered results
      const total = allOnus.length
      const totalPages = Math.ceil(total / limit)
      const paginatedOnus = allOnus.slice(skip, skip + limit)

      return {
        onus: paginatedOnus,
        total,
        page,
        limit,
        totalPages,
      }
    }

    // For port filtering (Frame/Slot/Port), we need to do additional filtering in memory
    // because Prisma doesn't support complex string parsing in queries
    if (filters.port && !filters.signal) {
      allOnus = await this.client.onu.findMany({
        where: whereClause,
        orderBy: { lastUpdate: 'desc' },
        include: {
          olt: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      }) as OnuPublic[]

      // More precise port filtering - Format: "Frame/Slot/Port"
      const [frame, slot, portNum] = filters.port.split('/').map(Number)
      allOnus = allOnus.filter((onu) => {
        // Format: Frame/Slot/Port:OnuID
        const match = onu.gponOnu.match(/^(\d+)\/(\d+)\/(\d+):/)
        if (match) {
          const onuFrame = parseInt(match[1] ?? '0', 10)
          const onuSlot = parseInt(match[2] ?? '0', 10)
          const onuPort = parseInt(match[3] ?? '0', 10)
          return onuFrame === frame && onuSlot === slot && onuPort === portNum
        }
        return false
      })

      const total = allOnus.length
      const totalPages = Math.ceil(total / limit)
      const paginatedOnus = allOnus.slice(skip, skip + limit)

      return {
        onus: paginatedOnus,
        total,
        page,
        limit,
        totalPages,
      }
    }

    // For card filtering (Frame/Slot), we need to do additional filtering in memory
    if (filters.card && !filters.signal && !filters.port) {
      allOnus = await this.client.onu.findMany({
        where: whereClause,
        orderBy: { lastUpdate: 'desc' },
        include: {
          olt: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      }) as OnuPublic[]

      // More precise card filtering - Format: "Frame/Slot"
      const [frame, slot] = filters.card.split('/').map(Number)
      allOnus = allOnus.filter((onu) => {
        // Format: Frame/Slot/Port:OnuID
        const match = onu.gponOnu.match(/^(\d+)\/(\d+)\/(\d+):/)
        if (match) {
          const onuFrame = parseInt(match[1] ?? '0', 10)
          const onuSlot = parseInt(match[2] ?? '0', 10)
          return onuFrame === frame && onuSlot === slot
        }
        return false
      })

      const total = allOnus.length
      const totalPages = Math.ceil(total / limit)
      const paginatedOnus = allOnus.slice(skip, skip + limit)

      return {
        onus: paginatedOnus,
        total,
        page,
        limit,
        totalPages,
      }
    }

    // Standard query with pagination (no signal or precise port filtering)
    const [onus, total] = await Promise.all([
      this.client.onu.findMany({
        where: whereClause,
        orderBy: [{ oltId: 'asc' }, { gponOnu: 'asc' }], // Stable sorting
        skip,
        take: limit,
        include: {
          olt: {
            select: {
              id: true,
              name: true,
            },
          },
        },
        // Explicitly include OID fields to ensure they're returned
      }),
      this.client.onu.count({ where: whereClause }),
    ])

    const totalPages = Math.ceil(total / limit)

    return {
      onus: onus as OnuPublic[],
      total,
      page,
      limit,
      totalPages,
    }
  }

  async findByOltId(oltId: string): Promise<OnuPublic[]> {
    const onus = await this.client.onu.findMany({
      where: { oltId },
      orderBy: { gponOnu: 'asc' },
      include: {
        olt: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    })
    return onus as OnuPublic[]
  }

  async findByGponOnu(oltId: string, gponOnu: string): Promise<OnuPublic | null> {
    const onu = await this.client.onu.findUnique({
      where: {
        oltId_gponOnu: {
          oltId,
          gponOnu,
        },
      },
      include: {
        olt: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    })
    return onu as OnuPublic | null
  }

  async create(data: OnuCreateData): Promise<{ id: string }> {
    const onu = await this.client.onu.create({
      data: {
        ...data,
        id: randomUUID(),
        lastUpdate: new Date(),
        updatedAt: new Date(),
      },
      select: { id: true },
    })
    return onu
  }

  async upsert(oltId: string, gponOnu: string, data: OnuCreateData): Promise<{ id: string; updated: boolean }> {
    // Cek apakah data sudah ada
    const existing = await this.client.onu.findUnique({
      where: {
        oltId_gponOnu: {
          oltId,
          gponOnu,
        },
      },
    })

    if (existing) {
      // Hanya update field yang berubah untuk optimasi
      const updateData: Prisma.OnuUpdateInput = {}
      let hasChanges = false

      // Compare dan hanya update field yang berbeda
      const fieldsToCheck: (keyof OnuCreateData)[] = [
        'name', 'description', 'pppoe', 'status', 'rxOlt', 'rxOnu', 'txOlt', 'txOnu',
        'serialNumber', 'actualType', 'registerTime', 'distance', 'lastSeen',
        'registrationMode', 'softwareVersion', 'hardwareVersion', 'temperature',
        'laserBiasCurrent', 'vendorId', 'equipmentId', 'firmwareVersion',
        'macAddress', 'batteryStatus', 'opticalTransceiverType', 'lastDeregTime',
        'authMode', 'loid', 'password', 'configState', 'powerLevel', 'dyingGaspTime',
        'rxPowerStatus', 'txPowerStatus', 'rxBytes', 'txBytes', 'rxPackets', 'txPackets',
        'rxErrors', 'txErrors', 'rxDrops', 'txDrops', 'wifiEnable', 'wifiSsid',
        'wifiSecurityMode', 'wifiChannel'
      ]

      for (const field of fieldsToCheck) {
        const newValue = data[field]
        const oldValue = existing[field as keyof typeof existing]

        // Compare values (handle null/undefined)
        if (newValue !== undefined) {
          let isDifferent = false

          // Handle null comparison
          if (newValue === null && oldValue === null) {
            isDifferent = false
          } else if (newValue === null || oldValue === null) {
            isDifferent = true
          }
          // Deep comparison for dates
          else if (newValue instanceof Date && oldValue instanceof Date) {
            isDifferent = newValue.getTime() !== oldValue.getTime()
          }
          // Handle bigint comparison
          else if (typeof newValue === 'bigint' && typeof oldValue === 'bigint') {
            isDifferent = newValue !== oldValue
          }
          // Regular comparison
          else {
            isDifferent = newValue !== oldValue
          }

          if (isDifferent) {
            (updateData as any)[field] = newValue
            hasChanges = true
          }
        }
      }

      // Jika ada perubahan, update
      if (hasChanges) {
        updateData.lastUpdate = new Date()
        updateData.updatedAt = new Date()
        await this.client.onu.update({
          where: {
            oltId_gponOnu: {
              oltId,
              gponOnu,
            },
          },
          data: updateData,
        })
        return { id: existing.id, updated: true }
      } else {
        // Tidak ada perubahan, skip update
        return { id: existing.id, updated: false }
      }
    } else {
      // Insert baru
      const onu = await this.client.onu.create({
        data: {
          ...data,
          oltId,
          gponOnu,
          id: randomUUID(),
          lastUpdate: new Date(),
          updatedAt: new Date(),
        },
        select: { id: true },
      })
      return { id: onu.id, updated: true }
    }
  }

  async update(id: string, data: OnuUpdateData): Promise<void> {
    await this.client.onu.update({
      where: { id },
      data: {
        ...data,
        lastUpdate: data.lastUpdate || new Date(),
        updatedAt: new Date(),
      },
    })
  }

  async delete(id: string): Promise<void> {
    await this.client.onu.delete({
      where: { id },
    })
  }

  async deleteByOltId(oltId: string): Promise<void> {
    await this.client.onu.deleteMany({
      where: { oltId },
    })
  }

  async count(): Promise<number> {
    return await this.client.onu.count()
  }

  async countByOltId(oltId: string): Promise<number> {
    return await this.client.onu.count({
      where: { oltId },
    })
  }

  async countByStatus(status: string): Promise<number> {
    return await this.client.onu.count({
      where: { status },
    })
  }

  /**
   * Find ONUs with pagination and caching support
   * Optimized for large-scale ONU data with selective field projection
   */
  async findPaginatedOptimized(params: {
    oltId?: string
    page: number
    limit: number
    status?: string
    search?: string
    useCache?: boolean
  }): Promise<PaginatedOnuResult> {
    const { oltId, page, limit, status, search, useCache = true } = params

    // Try cache first if enabled and oltId is provided (no search/filter)
    if (useCache && oltId && !search && !status) {
      const cached = await onuCacheService.getCachedOltOnus(oltId)
      if (cached) {
        // Apply pagination to cached data
        const skip = (page - 1) * limit
        const total = cached.length
        const totalPages = Math.ceil(total / limit)
        const paginatedData = cached.slice(skip, skip + limit)

        return {
          onus: paginatedData as any,
          total,
          page,
          limit,
          totalPages,
        }
      }
    }

    // Build where clause
    const whereConditions: Prisma.OnuWhereInput[] = []

    if (oltId) {
      whereConditions.push({ oltId })
    }

    if (status) {
      whereConditions.push({ status })
    }

    if (search) {
      whereConditions.push({
        OR: [
          { name: { contains: search, mode: 'insensitive' } },
          { description: { contains: search, mode: 'insensitive' } },
          { pppoe: { contains: search, mode: 'insensitive' } },
          { serialNumber: { contains: search, mode: 'insensitive' } },
          { macAddress: { contains: search, mode: 'insensitive' } },
        ],
      })
    }

    const whereClause: Prisma.OnuWhereInput =
      whereConditions.length > 0 ? { AND: whereConditions } : {}

    const skip = (page - 1) * limit

    // Optimized query with selective field projection
    // Don't select heavy fields like rxBytes, txBytes, etc. for list view
    const [onus, total] = await Promise.all([
      this.client.onu.findMany({
        where: whereClause,
        skip,
        take: limit,
        orderBy: [{ oltId: 'asc' }, { gponOnu: 'asc' }],
        select: {
          id: true,
          oltId: true,
          name: true,
          description: true,
          pppoe: true,
          gponOnu: true,
          status: true,
          rxOlt: true,
          rxOnu: true,
          txOlt: true,
          txOnu: true,
          serialNumber: true,
          actualType: true,
          registerTime: true,
          distance: true,
          lastSeen: true,
          macAddress: true,
          temperature: true,
          lastUpdate: true,
          olt: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      }),
      this.client.onu.count({ where: whereClause }),
    ])

    const totalPages = Math.ceil(total / limit)
    const result = {
      onus: onus as OnuPublic[],
      total,
      page,
      limit,
      totalPages,
    }

    // Cache if no filters (just oltId pagination)
    if (useCache && oltId && !search && !status && page === 1) {
      // Only cache first page of unfiltered data
      await onuCacheService.cacheOltOnus(oltId, onus as any)
    }

    return result
  }

  /**
   * Get ONUs by OLT ID with caching
   */
  async findByOltIdCached(oltId: string, useCache: boolean = true): Promise<OnuPublic[]> {
    // Try cache first
    if (useCache) {
      const cached = await onuCacheService.getCachedOltOnus(oltId)
      if (cached) {
        return cached as any
      }
    }

    // Fetch from database
    const onus = await this.findByOltId(oltId)

    // Cache result
    if (useCache) {
      await onuCacheService.cacheOltOnus(oltId, onus as any)
    }

    return onus
  }

  async getSummaryStats(oltId?: string): Promise<OnuSummaryStats> {
    const whereClause: Prisma.OnuWhereInput = oltId ? { oltId } : {}

    // First get raw status counts
    const [total, onlineOnus, offline, los, dyingGasp, uncfg, disabled] = await Promise.all([
      this.client.onu.count({ where: whereClause }),
      // Fetch online ONUs signal data for quality classification
      this.client.onu.findMany({
        where: { ...whereClause, status: 'Online' },
        select: { rxOlt: true }
      }),
      this.client.onu.count({ where: { ...whereClause, status: 'Offline' } }),
      this.client.onu.count({ where: { ...whereClause, status: 'LOS' } }),
      this.client.onu.count({ where: { ...whereClause, status: 'DyingGasp' } }),
      this.client.onu.count({ where: { ...whereClause, status: { contains: 'Unconf', mode: 'insensitive' } } }),
      this.client.onu.count({ where: { ...whereClause, status: 'Disabled' } }),
    ])

    // Calculate signal quality stats for online ONUs
    let good = 0
    let warning = 0
    let critical = 0

    // Helper to parse dBm
    const parseDbm = (val: string | null): number | null => {
      if (!val) return null
      const num = parseFloat(val.replace(' dBm', ''))
      return isNaN(num) ? null : num
    }

    for (const onu of onlineOnus) {
      const rx = parseDbm(onu.rxOlt)
      if (rx !== null) {
        if (rx >= -26.00) {
          good++
        } else if (rx >= -28.00) {
          warning++
        } else {
          critical++
        }
      } else {
        // If no signal data but online, count as simple online or decide grouping
        // For now we might put them in good or ignore
        good++
      }
    }

    // Reconcile 'Online' count. 
    // In summaryData interface of page.tsx:
    // good.count = Online with good signal
    // warning.count = Online with warning signal
    // critical.count = Online with critical signal + LOS count (usually handled in separate bucket in UI)

    // BUT the frontend expectation for "Good" usually refers to "Online Good".
    // "Critical" in frontend usually refers to LOS + Online Critical Signal.
    // Let's stick to returning categorized counts.

    // The interface OnuSummaryStats we defined in IOnuRepository.ts currently only has basic fields.
    // We should ensure IOnuRepository has fields for good/warning/critical signal counts if we want to return them detailed.
    // OR we return basic fields and let frontend approximate? 
    // Wait, the page.tsx fetchSummary maps:
    // good: { count: data.online || 0 ... } -> This blindly mapped 'online' count to 'good'.
    // We need to return structured data matching what frontend can consume or update frontend.
    // Current IOnuRepository returns: { total, online, offline, los, dyingGasp, uncfg, disabled }
    // We should ADD signal quality fields to OnuSummaryStats interface first.

    // Let's create an extended object and cast it, or update IOnuRepository first.
    // Modifying IOnuRepository is safer.

    return {
      total,
      online: onlineOnus.length, // Keep total online for reference
      offline,
      los,
      dyingGasp,
      uncfg,
      disabled,
      // Add detailed breakdown
      goodSignal: good,
      warningSignal: warning,
      criticalSignal: critical
    } as OnuSummaryStats
  }

  /**
   * Invalidate cache after sync
   */
  async invalidateCache(oltId?: string): Promise<void> {
    if (oltId) {
      await onuCacheService.invalidateOltCache(oltId)
    } else {
      await onuCacheService.invalidateAllCaches()
    }
  }

  /**
   * Minimal batch fetch for ONU OIDs - optimized for OnuService batch updates
   * Single query to get all ONUs for an OLT with only needed fields
   */
  async findManyByOltIdMinimal(oltId: string): Promise<Array<{
    gponOnu: string
    statusOid: string | null
    rxOltOid: string | null
    rxOnuOid: string | null
    nameOid: string | null
    descOid: string | null
    compositeIndex: number | null
    status: string | null
    rxOlt: string | null
    rxOnu: string | null
    name: string | null
    description: string | null
    pppoe: string | null
    serialNumber: string | null
    actualType: string | null
  }>> {
    return this.client.onu.findMany({
      where: { oltId },
      select: {
        gponOnu: true,
        statusOid: true,
        rxOltOid: true,
        rxOnuOid: true,
        nameOid: true,
        descOid: true,
        compositeIndex: true,
        status: true,
        rxOlt: true,
        rxOnu: true,
        name: true,
        description: true,
        pppoe: true,
        serialNumber: true,
        actualType: true,
      }
    })
  }
}

import { type Server as SocketIOServer } from 'socket.io';
import { getOLTRepository, getOnuRepository } from '@/lib/repositories';
import { updateMultipleOnusViaGetWithOids } from './onu-update-snmp-get';
import { type OnuSyncData } from '@/lib/types/onu-sync';

export class OnuService {
    private io: SocketIOServer | null = null;

    constructor(io?: SocketIOServer) {
        if (io) {
            this.io = io;
        } else if (globalThis.socketIOServer) {
            this.io = globalThis.socketIOServer;
        }
    }

    setSocketServer(io: SocketIOServer) {
        this.io = io;
    }

    async updateOnus(onuList: { gponOnu: string; oltId: string }[]) {
        if (!onuList || onuList.length === 0) return [];

        console.log(`[OnuService] Updating ${onuList.length} ONUs...`);

        // Group ONUs by OLT
        const onusByOlt = new Map<string, Array<{ gponOnu: string }>>();

        for (const onu of onuList) {
            if (!onu.gponOnu || !onu.oltId) continue;
            if (!onusByOlt.has(onu.oltId)) {
                onusByOlt.set(onu.oltId, []);
            }
            onusByOlt.get(onu.oltId)!.push({ gponOnu: onu.gponOnu });
        }

        const updatedOnus: Array<{
            gponOnu: string;
            oltId: string;
            updated: boolean;
            data?: Partial<OnuSyncData>;
        }> = [];

        const oltRepo = getOLTRepository();
        const onuRepo = getOnuRepository();

        // Process per OLT
        for (const [oltId, onus] of onusByOlt.entries()) {
            try {
                const olt = await oltRepo.findById(oltId);
                if (!olt || !olt.snmpConnected || !olt.snmpCommunityWrite) {
                    onus.forEach(o => updatedOnus.push({ gponOnu: o.gponOnu, oltId, updated: false }));
                    continue;
                }

                // OPTIMIZATION: Single batch query instead of N queries
                // This replaces Promise.all(map findByGponOnu) pattern
                const existingOnus = await onuRepo.findManyByOltIdMinimal(oltId);

                // Create Map for O(1) lookup (instead of async query per ONU)
                const onuMap = new Map(
                    existingOnus.map(o => [o.gponOnu, o])
                );

                // Map OIDs using cached data (no queries)
                const onusWithOids = onus.map((onu) => {
                    const existingOnu = onuMap.get(onu.gponOnu);
                    return {
                        gponOnu: onu.gponOnu,
                        statusOid: existingOnu?.statusOid || null,
                        rxOltOid: existingOnu?.rxOltOid || null,
                        rxOnuOid: existingOnu?.rxOnuOid || null,
                        nameOid: existingOnu?.nameOid || null,
                        descOid: existingOnu?.descOid || null,
                        compositeIndex: existingOnu?.compositeIndex || null,
                    };
                });

                // SNMP GET
                const updatedData = await updateMultipleOnusViaGetWithOids(
                    olt.ipAddress,
                    olt.snmpPort || 161,
                    olt.snmpCommunityWrite,
                    olt.snmpVersion || '2c',
                    onusWithOids
                );

                // Update DB - reuse cached data from onuMap
                for (const uData of updatedData) {
                    if (!uData.gponOnu || !uData.status) {
                        updatedOnus.push({ gponOnu: uData.gponOnu!, oltId, updated: false });
                        continue;
                    }

                    try {
                        // Reuse cached data instead of another query
                        const existingOnu = onuMap.get(uData.gponOnu);
                        const upsertData: Partial<OnuSyncData> = {
                            oltId,
                            gponOnu: uData.gponOnu,
                            lastSeen: new Date(),
                            status: uData.status !== 'Unknown' ? uData.status : (existingOnu?.status || 'Unknown'),
                            rxOlt: (uData.rxOlt && uData.rxOlt !== 'N/A') ? uData.rxOlt : existingOnu?.rxOlt,
                            rxOnu: (uData.rxOnu && uData.rxOnu !== 'N/A') ? uData.rxOnu : existingOnu?.rxOnu,
                            // Use existing values for other fields if not provided
                            name: uData.name || existingOnu?.name || '',
                            description: uData.description ?? existingOnu?.description ?? null,
                            pppoe: uData.pppoe || existingOnu?.pppoe || null,
                            serialNumber: uData.serialNumber || existingOnu?.serialNumber || null,
                            actualType: uData.actualType || existingOnu?.actualType || null,
                        };

                        await onuRepo.upsert(oltId, uData.gponOnu, upsertData as any);

                        const result = {
                            gponOnu: uData.gponOnu,
                            oltId,
                            updated: true,
                            data: uData
                        };
                        updatedOnus.push(result);

                        // Emit WebSocket event
                        if (this.io) {
                            this.io.to('admin:onu').emit('onu:updated', result);
                        }

                    } catch (err) {
                        console.error(`[OnuService] Update error ${uData.gponOnu}: `, err);
                        updatedOnus.push({ gponOnu: uData.gponOnu, oltId, updated: false });
                    }
                }

            } catch (err) {
                console.error(`[OnuService] OLT ${oltId} error: `, err);
                onus.forEach(o => updatedOnus.push({ gponOnu: o.gponOnu, oltId, updated: false }));
            }
        }

        return updatedOnus;
    }
}

// Singleton instance
let onuServiceInstance: OnuService | null = null;
export function getOnuService(): OnuService {
    if (!onuServiceInstance) {
        onuServiceInstance = new OnuService();
    }
    return onuServiceInstance;
}

/**
 * Optimized Bulk ONU Sync Service - Phase 3
 * 
 * Performance optimizations:
 * 1. SNMP WALK for bulk index retrieval (faster than individual GETs)
 * 2. Concurrent batch processing (5 batches in parallel)
 * 3. Smart rate limiting to protect OLT
 * 4. Progress tracking for UI updates
 * 5. Automatic cache invalidation
 * 
 * Target: Sync 1000 ONUs in 3-5 minutes (vs 20-30 minutes before)
 */

import { OLTRepository, OnuRepository } from '../repositories'
import { logger } from '../../../lib/logger'
import snmp from 'net-snmp'
import { type OnuSyncData } from '@/lib/types/onu-sync'

interface OltSyncParams {
    ipAddress: string;
    id: string; // Added ID for OnuSyncData
    snmpCommunityWrite?: string | null;
    snmpPort: number;
    snmpVersion: string;
}

interface SyncProgress {
    phase: 'counting' | 'fetching' | 'saving' | 'complete'
    percentage: number
    current: number
    total: number
    message: string
}

interface BulkSyncResult {
    success: boolean
    synced: number
    errors: number
    duration: number
}

/**
 * Optimized bulk sync service
 */
export class OnuBulkSyncService {
    private static readonly BATCH_SIZE = 50 // Process 50 ONUs per batch
    private static readonly MAX_CONCURRENT_BATCHES = 5 // Max 5 batches in parallel
    private static readonly RATE_LIMIT_DELAY = 100 // 100ms between batches
    private static readonly SNMP_TIMEOUT = 10000 // 10 second timeout
    private static readonly SNMP_RETRIES = 3 // Retry 3 times on failure

    /**
     * Sync ONUs for a specific OLT with progress tracking
     */
    async syncOltOnus(
        oltId: string,
        onProgress?: (progress: SyncProgress) => void
    ): Promise<BulkSyncResult> {
        const startTime = Date.now()

        try {
            const oltRepo = new OLTRepository()
            const onuRepo = new OnuRepository()

            // Get OLT info
            const olt = await oltRepo.findById(oltId)
            if (!olt) {
                throw new Error(`OLT with ID ${oltId} not found`)
            }

            if (!olt.snmpConnected || !olt.snmpCommunityWrite) {
                throw new Error(`OLT ${olt.name} is not connected via SNMP`)
            }

            logger.info(`Starting optimized bulk sync for OLT ${olt.name}`, {
                oltId,
                ipAddress: olt.ipAddress,
            })

            // Phase 1: Count ONUs (fast)
            this.reportProgress(onProgress, {
                phase: 'counting',
                percentage: 5,
                current: 0,
                total: 0,
                message: 'Counting ONUs...',
            })

            const onuIndexes = await this.walkOnuIndexes(olt)
            const totalOnus = onuIndexes.length

            logger.info(`Found ${totalOnus} ONUs on OLT ${olt.name}`)

            if (totalOnus === 0) {
                return {
                    success: true,
                    synced: 0,
                    errors: 0,
                    duration: Date.now() - startTime,
                }
            }

            // Phase 2: Fetch ONU data in parallel batches
            this.reportProgress(onProgress, {
                phase: 'fetching',
                percentage: 10,
                current: 0,
                total: totalOnus,
                message: `Fetching ${totalOnus} ONUs...`,
            })

            const onus = await this.fetchOnusInParallel(
                olt,
                onuIndexes,
                (fetched) => {
                    const fetchProgress = 10 + Math.floor((fetched / totalOnus) * 40) // 10-50%
                    this.reportProgress(onProgress, {
                        phase: 'fetching',
                        percentage: fetchProgress,
                        current: fetched,
                        total: totalOnus,
                        message: `Fetched ${fetched}/${totalOnus} ONUs`,
                    })
                }
            )

            logger.info(`Fetched ${onus.length} ONUs from OLT ${olt.name}`)

            // Phase 3: Save to database in batches
            this.reportProgress(onProgress, {
                phase: 'saving',
                percentage: 50,
                current: 0,
                total: onus.length,
                message: 'Saving ONUs to database...',
            })

            let saved = 0
            let errors = 0

            const batches = this.chunkArray(onus, OnuBulkSyncService.BATCH_SIZE)

            for (let i = 0; i < batches.length; i++) {
                const batch = batches[i]

                // Save batch
                const results = await Promise.allSettled(
                    batch.map(onu =>
                        onuRepo.upsert(oltId, onu.gponOnu, {
                            oltId,
                            name: onu.name || '',
                            description: onu.description,
                            gponOnu: onu.gponOnu,
                            status: onu.status || 'Unknown',
                            rxOlt: onu.rxOlt,
                            rxOnu: onu.rxOnu,
                            serialNumber: onu.serialNumber,
                            actualType: onu.actualType,
                            lastSeen: new Date(),
                        })
                    )
                )

                // Count successes
                results.forEach(r => {
                    if (r.status === 'fulfilled') saved++
                    else errors++
                })

                // Report progress
                const saveProgress = 50 + Math.floor(((i + 1) / batches.length) * 45) // 50-95%
                this.reportProgress(onProgress, {
                    phase: 'saving',
                    percentage: saveProgress,
                    current: saved,
                    total: onus.length,
                    message: `Saved ${saved}/${onus.length} ONUs`,
                })

                // Rate limiting between batches
                if (i < batches.length - 1) {
                    await this.sleep(OnuBulkSyncService.RATE_LIMIT_DELAY)
                }
            }

            // Update OLT sync timestamp
            await oltRepo.update(oltId, {
                onuLastSync: new Date(),
            })

            // Invalidate cache
            await onuRepo.invalidateCache(oltId)

            // Complete
            this.reportProgress(onProgress, {
                phase: 'complete',
                percentage: 100,
                current: saved,
                total: saved,
                message: `Sync complete! Saved ${saved} ONUs`,
            })

            const duration = Date.now() - startTime
            logger.info(`Bulk sync completed for OLT ${olt.name}`, {
                synced: saved,
                errors,
                duration: `${(duration / 1000).toFixed(2)}s`,
            })

            return {
                success: true,
                synced: saved,
                errors,
                duration,
            }
        } catch (error) {
            logger.error('Bulk sync failed', error instanceof Error ? error : new Error(String(error)), { oltId })
            throw error
        }
    }

    /**
     * Walk ONU table to get all indexes (much faster than individual GETs)
     */
    private async walkOnuIndexes(olt: OltSyncParams): Promise<number[]> {
        return new Promise((resolve, reject) => {
            const session = snmp.createSession(
                olt.ipAddress,
                olt.snmpCommunityWrite || 'public',
                {
                    port: olt.snmpPort || 161,
                    retries: OnuBulkSyncService.SNMP_RETRIES,
                    timeout: OnuBulkSyncService.SNMP_TIMEOUT,
                    version: olt.snmpVersion === '1' ? snmp.Version1 : snmp.Version2c,
                }
            )

            const baseOid = '1.3.6.1.4.1.3902.1012.3.28.1.1.1' // ONU index table
            const indexes: number[] = []

            session.walk(
                baseOid,
                20, // maxRepetitions
                (varbinds) => {
                    varbinds.forEach(vb => {
                        if (snmp.isVarbindError(vb)) return

                        // Extract composite index from OID
                        const oidParts = vb.oid.split('.')
                        const compositeIndex = parseInt(oidParts[oidParts.length - 1], 10)

                        if (!isNaN(compositeIndex) && compositeIndex > 0) {
                            indexes.push(compositeIndex)
                        }
                    })
                },
                (error) => {
                    session.close()
                    if (error) {
                        logger.error('SNMP walk failed', error instanceof Error ? error : new Error(String(error)))
                        reject(error)
                    } else {
                        // Remove duplicates and sort
                        const uniqueIndexes = Array.from(new Set(indexes)).sort((a, b) => a - b)
                        resolve(uniqueIndexes)
                    }
                }
            )
        })
    }

    /**
     * Fetch ONUs in parallel batches for maximum speed
     */
    private async fetchOnusInParallel(
        olt: OltSyncParams,
        indexes: number[],
        onProgress?: (fetched: number) => void
    ): Promise<OnuSyncData[]> {
        const batches = this.chunkArray(indexes, OnuBulkSyncService.BATCH_SIZE)
        const allOnus: OnuSyncData[] = []
        let fetchedCount = 0

        // Process batches with concurrency limit
        for (let i = 0; i < batches.length; i += OnuBulkSyncService.MAX_CONCURRENT_BATCHES) {
            const concurrentBatches = batches.slice(i, i + OnuBulkSyncService.MAX_CONCURRENT_BATCHES)

            const results = await Promise.allSettled(
                concurrentBatches.map(batch => this.fetchOnuBatch(olt, batch))
            )

            results.forEach(result => {
                if (result.status === 'fulfilled') {
                    allOnus.push(...result.value)
                    fetchedCount += result.value.length
                    onProgress?.(fetchedCount)
                }
            })

            // Rate limit between concurrent batch groups
            if (i + OnuBulkSyncService.MAX_CONCURRENT_BATCHES < batches.length) {
                await this.sleep(OnuBulkSyncService.RATE_LIMIT_DELAY)
            }
        }

        return allOnus
    }

    /**
     * Fetch a batch of ONUs using SNMP GET
     */
    private async fetchOnuBatch(olt: OltSyncParams, indexes: number[]): Promise<OnuSyncData[]> {
        return new Promise((resolve, reject) => {
            const session = snmp.createSession(
                olt.ipAddress,
                olt.snmpCommunityWrite || 'public',
                {
                    port: olt.snmpPort || 161,
                    retries: OnuBulkSyncService.SNMP_RETRIES,
                    timeout: OnuBulkSyncService.SNMP_TIMEOUT,
                    version: olt.snmpVersion === '1' ? snmp.Version1 : snmp.Version2c,
                }
            )

            // Build OIDs for bulk GET
            const oids = indexes.flatMap(idx => [
                `1.3.6.1.4.1.3902.1012.3.28.1.1.3.${idx}`, // Name
                `1.3.6.1.4.1.3902.1012.3.28.2.1.4.${idx}`, // Status
                `1.3.6.1.4.1.3902.1012.3.28.2.1.7.${idx}`, // RX OLT
                `1.3.6.1.4.1.3902.1012.3.28.2.1.8.${idx}`, // RX ONU
                `1.3.6.1.4.1.3902.1012.3.50.12.1.1.10.${idx}`, // Serial Number
            ])

            session.get(oids, (error, varbinds) => {
                session.close()

                if (error) {
                    reject(error)
                    return
                }

                if (!varbinds) {
                    resolve([])
                    return
                }

                const onus: OnuSyncData[] = []

                // Parse results (every 5 OIDs = 1 ONU)
                for (let i = 0; i < indexes.length; i++) {
                    const baseIdx = i * 5
                    const compositeIndex = indexes[i]

                    // Decode gponOnu from composite index
                    const frame = Math.floor(compositeIndex / 16777216)
                    const slot = Math.floor((compositeIndex % 16777216) / 65536)
                    const port = Math.floor((compositeIndex % 65536) / 256)
                    const onuId = compositeIndex % 256

                    const onu: OnuSyncData = {
                        gponOnu: `${frame}/${slot}/${port}:${onuId}`,
                        name: this.parseValue(varbinds[baseIdx]) || 'Unknown',
                        status: this.parseStatus(varbinds[baseIdx + 1]),
                        rxOlt: this.parseValue(varbinds[baseIdx + 2]),
                        rxOnu: this.parseValue(varbinds[baseIdx + 3]),
                        serialNumber: this.parseValue(varbinds[baseIdx + 4]),
                        oltId: olt.id,

                        // Initialize required fields with null/defaults
                        txOlt: null,
                        txOnu: null,
                        actualType: null,
                        description: null,
                        pppoe: null,
                        registerTime: null,
                        distance: null,
                        lastSeen: new Date(),
                        registrationMode: null,
                        softwareVersion: null,
                        hardwareVersion: null,
                        temperature: null,
                        laserBiasCurrent: null,
                        vendorId: null,
                        equipmentId: null,
                        firmwareVersion: null,
                        macAddress: null,
                        batteryStatus: null,
                        opticalTransceiverType: null,
                        lastDeregTime: null,
                        authMode: null,
                        loid: null,
                        password: null,
                        configState: null,
                        powerLevel: null,
                        dyingGaspTime: null,
                        rxPowerStatus: null,
                        txPowerStatus: null,
                        rxBytes: null,
                        txBytes: null,
                        rxPackets: null,
                        txPackets: null,
                        rxErrors: null,
                        txErrors: null,
                        rxDrops: null,
                        txDrops: null,
                        wifiEnable: null,
                        wifiSsid: null,
                        wifiSecurityMode: null,
                        wifiChannel: null,
                    }

                    onus.push(onu)
                }

                resolve(onus)
            })
        })
    }

    /**
     * Parse SNMP value
     */
    private parseValue(varbind: any): string | null {
        if (!varbind || snmp.isVarbindError(varbind)) return null

        if (Buffer.isBuffer(varbind.value)) {
            return varbind.value.toString('utf8').replace(/\0/g, '').trim()
        }

        return String(varbind.value || '').trim() || null
    }

    /**
     * Parse ONU status
     */
    private parseStatus(varbind: any): string {
        const value = this.parseValue(varbind)
        if (!value) return 'Unknown'

        const statusMap: Record<string, string> = {
            '1': 'Online',
            '2': 'Offline',
            '3': 'LOS',
            '4': 'DyingGasp',
        }

        return statusMap[value] || value
    }

    /**
     * Utility: Split array into chunks
     */
    private chunkArray<T>(array: T[], size: number): T[][] {
        const chunks: T[][] = []
        for (let i = 0; i < array.length; i += size) {
            chunks.push(array.slice(i, i + size))
        }
        return chunks
    }

    /**
     * Utility: Sleep
     */
    private sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms))
    }

    /**
     * Report progress
     */
    private reportProgress(
        callback: ((progress: SyncProgress) => void) | undefined,
        progress: SyncProgress
    ): void {
        if (callback) {
            try {
                callback(progress)
            } catch (error) {
                logger.error('Progress callback error', error instanceof Error ? error : new Error(String(error)))
            }
        }
    }
}

