      const mockBarang = {
        id: 'barang-1',
        kode: 'BRG-001',
        nama: 'Kabel Fiber',
        barangGudang: [] as any[]
      }

      prismaMock.barang.findUnique.mockResolvedValueOnce(mockBarang as any)

