  })

  describe('create', () => {
    it('should create new ONU successfully', async () => {
      const input = {
        oltId: 'olt-1',
        gponOnu: '1/1/1:1',
        name: 'ONU Customer A',
        serialNumber: 'HWTC123456',
        status: 'Online'
      }

      prismaMock.onu.create.mockResolvedValueOnce({
